 def logical_gate(gate_type, *args):
  if gate_type == 'AND':
  return eval(' AND({})'.format(', '.join(args)))
  elif gate_type == 'OR':
  return eval(' OR({})'.format(', '.join(args)))
  elif gate_type == 'NOT':
  return eval(' NOT({})'.format(args[0]))


