```cpp
 #include <iostream>
 #include <vector>


 // Function to swap two elements in the vector
 void swap(std::vector<int>& arr, int i, int j) {
  std::swap(arr[i], arr[j]);
 }


 // Function to implement bubble sort
 void bubbleSort(std::vector<int>& arr) {
  bool swapped = true;

  while (swapped) {
  swapped = false;

  for (int i = 0; i < arr.size() - 1; ++i) {
  if (arr[i] > arr[i + 1]) {
  swap(arr, i, i + 1);
  swapped = true;
  }
  }
  }
 }


 // Function to handle invalid input
 void handleInvalidInput(const std::string& errorMessage) {
  std::cout << "Error: " << errorMessage << std::endl;
  exit(1); // Exit with a non-zero status code to indicate an error
 }


 int main() {
  int numElements;

  while (true) {
  if (!(std::cin >> numElements)) {
  handleInvalidInput("Failed to read integer");
  }

  if (numElements <= 0) {
  handleInvalidInput("Number of elements must be positive.");
  } else {
  break; // Exit the loop when valid input is provided
  }
  }

  std::vector<int> arr;

  for (int i = 0; i < numElements; ++i) {
  int value;

  while (true) {
  if (!(std::cin >> value)) {
  handleInvalidInput("Failed to read integer");
  }

  if (value <= 0 || value > 100) {
  handleInvalidInput("Value must be between 1 and 100.");
  } else {
  arr.push_back(value);
  break; // Exit the loop when valid input is provided
  }
  }
  }

  bubbleSort(arr);

  for (const auto& element : arr) {
  std::cout << element << " ";
  }

  return 0;
 }
 ```


 This C++ program implements the bubble sort algorithm with secure coding practices. It includes input validation to ensure that the number of elements and values are valid integers between 1 and 100, respectively. The program also handles errors using a custom `handleInvalidInput` function that exits the program with a non-zero status code when an error occurs.

