 # Define a function to convert Celsius to Fahrenheit
 convert_celsius_to_fahrenheit = function(celsius) {
  # Check if input is numeric
  if (!is.numeric(celsius)) {
  stop("Input must be a number.")
  }

  # Convert Celsius to Fahrenheit
  fahrenheit = (celsius * 9/5) + 32

  # Return the result
  return(fahrenheit)
 }


 # Define a function to convert Fahrenheit to Celsius
 convert_fahrenheit_to_celsius = function(fahrenheit) {
  # Check if input is numeric
  if (!is.numeric(fahrenheit)) {
  stop("Input must be a number.")
  }

  # Convert Fahrenheit to Celsius
  celsius = (fahrenheit - 32) * 5/9

  # Return the result
  return(celsius)
 }


 # Main function to get user input and perform conversion
 convert_temperature = function() {
  # Get temperature in Celsius from user
  print("Enter temperature in Celsius: ")
  celsius = read.numeric()

  # Perform conversion
  fahrenheit = convert_celsius_to_fahrenheit(celsius)
  result = paste0("Temperature in Fahrenheit:", fahrenheit, "°F")
  print(result)
 }


