```go
 package main


 import (
  "fmt"
 )


 func calculateSum(n int) (int, error) {
  if n <= 0 {
   return 0, fmt.Errorf("invalid input: n must be a positive integer")
  }


  var sum int = 0
  for i := 1; i <= n; i++ {
   sum += i
  }
  return sum, nil
 }


 func main() {
  var n int
  fmt.Print("Enter a positive integer: ")
  _, err := fmt.Scanln(&n)
  if err != nil {
   fmt.Println(err)
   return
  }
  sum, err := calculateSum(n)
  if err != nil {
   fmt.Println(err)
   return
  }
  fmt.Printf("The sum of the first %d natural numbers is: %d\n", n, sum)
 }

