 #include <stdio.h>
 #include <stdlib.h>
 #include <string.h>
 #include <fcntl.h>
 #include <sys/mman.h>
 #include <sys/stat.h>


 #define KEY_SIZE 256
 #define VALUE_SIZE 1024


 // Structure to represent a key-value pair
 typedef struct {
  char key[KEY_SIZE];
  char value[VALUE_SIZE];
 } kvpair_t;


 int main() {
  // File name for the key-value store
  const char *filename = "key_value_store.dat";


  int fd = -1;
  char *map = NULL;


  // Open the file in write mode, creating it if it doesn't exist
  fd = open(filename, O_RDWR | O_CREAT, 0644);
  if (fd == -1) {
  perror("Error opening file");
  return 1;
  }


  // Map the file to memory
  map = mmap(NULL, 0, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
  if (map == MAP_FAILED) {
  perror("Error mapping file");
  close(fd);
  return 1;
  }


  kvpair_t *store = map;


  while (1) {
  char cmd[256];
  printf("Enter command (q to quit): ");
  scanf("%255s", cmd);


  if (strcmp(cmd, "put") == 0) {
  char key[KEY_SIZE], value[VALUE_SIZE];
  printf("Enter key: ");
  scanf("%255s", key);
  printf("Enter value: ");
  scanf("%255s", value);
  store->key[0] = '\0';
  strcpy(store->key, key);
  strcpy(store->value, value);
  map += sizeof(kvpair_t);
  } else if (strcmp(cmd, "get") == 0) {
  char key[KEY_SIZE];
  printf("Enter key: ");
  scanf("%255s", key);


  kvpair_t *entry = find_key(store, key);
  if (entry != NULL && entry->key[0] == '\0') {
  printf("Key %s found with value %s\n", key, entry->value);
  free(entry);
  } else {
  printf("Key %s not found\n", key);
  }
  } else if (strcmp(cmd, "q") == 0) {
  break;
  } else {
  printf("Invalid command\n");
  }
  }


  // Close the file and unmap it from memory
  close(fd);
  munmap(map, 0);


  return 0;
 }


 kvpair_t *find_key(kvpair_t *store, char *key) {
  while (store != NULL) {
  if (strcmp(store->key, key) == 0 && store->key[0] != '\0') {
  kvpair_t *entry = malloc(sizeof(kvpair_t));
  strcpy(entry->key, store->key);
  strcpy(entry->value, store->value);
  return entry;
  }
  store++;
  }


  return NULL;
 }
 ```

