 #include <stdio.h>
 #include <stdlib.h>


 #define MAX_SIZE 100


 int* merge_sorted_arrays(int* arr1, int m, int* arr2, int n) {
  if (arr1 == NULL || arr2 == NULL) {
  return arr1 ? arr1 : arr2;
  }


  int* merged = malloc((m + n) * sizeof(int));
  if (!merged) {
  return NULL; // out of memory
  }


  int p1 = 0, p2 = 0, p = 0;


  while (p1 < m && p2 < n) {
  if (arr1[p1] <= arr2[p2]) {
  merged[p++] = arr1[p1++];
  } else {
  merged[p++] = arr2[p2++];
  }
  }


  while (p1 < m) {
  merged[p++] = arr1[p1++];
  }


  while (p2 < n) {
  merged[p++] = arr2[p2++];
  }


  return merged;
 }


 int main() {
  int arr1[] = {1, 3, 5};
  int arr2[] = {2, 4, 6};


  int m = sizeof(arr1) / sizeof(arr1[0]);
  int n = sizeof(arr2) / sizeof(arr2[0]);


  printf("Merged array: ");
  int* merged = merge_sorted_arrays(arr1, m, arr2, n);
  if (merged != NULL) {
  for (int i = 0; i < m + n; i++) {
  printf("%d ", merged[i]);
  }
  } else {
  printf("Failed to allocate memory.");
  }


  free(merged);


  return 0;
 }
 ```


 This C program merges two sorted arrays using a secure approach. It includes input validation, error handling, and proper security measures. The `merge_sorted_arrays` function takes two sorted arrays as input and returns a new merged array. If the input arrays are NULL, it returns the first array. If memory allocation fails, it returns NULL. The program then prints the merged array and frees the allocated memory to prevent memory leaks.

