 class DowntimeReporter {
  public function __construct(array $urls) {
  if (!is_array($urls)) {
  throw new InvalidArgumentException('URLs must be an array');
  }
  foreach ($urls as $url) {
  if (!is_string($url)) {
  throw new InvalidArgumentException('Each URL must be a string');
  }
  if (empty($url)) {
  throw new InvalidArgumentException('URL cannot be empty');
  }
  }
  $this->urls = $urls;
