  public function report() {
  foreach ($this->urls as $url) {
  try {
  $startTime = microtime(true);
  $ch = curl_init($url);
  curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
  $response = curl_exec($ch);
  $endTime = microtime(true);
  $duration = $endTime - $startTime;
  if (empty($response)) {
  echo "$url is down.\n";
  return $duration;
  }
  } catch (Exception $e) {
  echo "Error pinging $url: " . $e->getMessage() . "\n";
  continue;
  }
  }
  }
 }


 $urls = [
  'http://example.com',
  'https://google.com',
  'invalid_url'
 ];


 $downtimeReporter = new DowntimeReporter($urls);
 echo $downtimeReporter->report();


