 package main


 import (
  "encoding/json"
  "fmt"
  "io/ioutil"
  "log"
  "net/http"
 )


 type Data struct {
  Title string `json:"title"`
  Author string `json:"author"`
 }


 func fetchAndParseJson(url string) ([]Data, error) {
  resp, err := http.Get(url)
  if err != nil {
   return nil, err
  }
  defer resp.Body.Close()


  body, err := ioutil.ReadAll(resp.Body)
  if err != nil {
   return nil, err
  }


  var data Data
  err = json.Unmarshal(body, &data)
  if err != nil {
   return nil, err
  }


  return []Data{data}, nil
 }


 func main() {
  url := "https://jsonplaceholder.typicode.com/posts"
  data, err := fetchAndParseJson(url)


  if err != nil {
   log.Fatal(err)
  }


  fmt.Printf("Title: %s\n", data[0].Title)
  fmt.Printf("Author: %s\n", data[0].Author)
 }
