```kotlin
 import java.util.*


 class SubCommand {
  val name: String = ""
  var arguments: List<String> = listOf()


  fun execute() {
  // Implement command execution logic here
  println("Executing subcommand $name with arguments ${arguments.joinToString(" ")}")
  }
 }


 fun main(args: Array<String>) {
  var parser = ProgramParser()
  val args = parser.parseArgs(args)


  if (args.command == null) {
  println("No command provided. Please use --help for usage.")
  return
  }


  when (args.command) {
  "hello" -> SubCommand(name = "hello").execute()
  "goodbye" -> SubCommand(name = "goodbye").execute()
  else -> {
  parser.printHelp()
  }
  }
 }


 class ProgramParser : CommandLineParser {
  override fun parseArgs(args: Array<String>): Args {
  var command = ""
  var argsList = mutableListOf<String>()


  for (i in args.indices) {
  when (args[i]) {
  "--help" -> return Args(command = null, args = listOf())
  "--version" -> return Args(command = "version", args = args.drop(i + 1))
  else -> {
  if (command != "") {
  command += " $args[i]"
  } else {
  command = args[i]
  }
  argsList.add(args[i])
  }
  }
  }


  if (command == "") {
  return Args(command = null, args = listOf())
  }


  return Args(command = command, args = argsList)
  }


  fun printHelp() {
  println("Usage: program [options] <subcommand> [arguments]")
  println("Options:")
  println("-h --help Show this message and exit")
  println("-v --version Program version")
  println()
  println("Subcommands:")
  println(" hello  Print Hello world!")
  println(" goodbye Print Goodbye world!")
  }
 }


 data class Args(val command: String?, val args: List<String> = listOf())
 ```

