 import java.util.HashMap;
 import java.util.Map;
 import java.util.Scanner;


 public class BankingSystem {


  private Map<String, Double> accounts = new HashMap<>();
  private Scanner scanner = new Scanner(System.in);


  public void run() {
  while (true) {
  System.out.println("1. Deposit");
  System.out.println("2. Withdraw");
  System.out.println("3. Check Balance");
  System.out.println("4. Exit");


  int choice = scanner.nextInt();
  scanner.nextLine(); // consume newline left-over


  switch (choice) {
  case 1:
  deposit();
  break;
  case 2:
  withdraw();
  break;
  case 3:
  checkBalance();
  break;
  case 4:
  System.exit(0);
  break;
  default:
  System.out.println("Invalid choice. Please choose a valid option.");
  }
  }
  }


  private void deposit() {
  String accountNumber = scanner.nextLine();
  double amount = getPositiveDoubleInput("Enter the amount to deposit: ");


  if (accounts.containsKey(accountNumber)) {
  accounts.put(accountNumber, accounts.get(accountNumber) + amount);
  } else {
  accounts.put(accountNumber, amount);
  }
  }


  private void withdraw() {
  String accountNumber = scanner.nextLine();
  double amount = getPositiveDoubleInput("Enter the amount to withdraw: ");


  if (accounts.containsKey(accountNumber)) {
  if (amount <= accounts.get(accountNumber)) {
  accounts.put(accountNumber, accounts.get(accountNumber) - amount);
  } else {
  System.out.println("Insufficient funds.");
  }
  } else {
  System.out.println("Account not found.");
  }
  }


  private void checkBalance() {
  String accountNumber = scanner.nextLine();
  double balance = accounts.getOrDefault(accountNumber, 0.0);


  System.out.println("Account balance: " + balance);
  }


  private double getPositiveDoubleInput(String prompt) {
  while (true) {
  try {
  String input = scanner.nextLine();
  double value = Double.parseDouble(input);


  if (value > 0) {
  return value;
  } else {
  System.out.println("Please enter a positive amount.");
  }
  } catch (NumberFormatException e) {
  System.out.println("Invalid input. Please enter a valid number.");
  }
  }
  }


  public static void main(String[] args) {
  BankingSystem bankingSystem = new BankingSystem();
  bankingSystem.run();
  }
 }
