 fun runTasksConcurrently(tasks: List<() -> Unit>, numThreads: Int): Job {
  if (tasks.isEmpty()) return FlowJob()
  val scope = CoroutineScope(Dispatchers.IO)
  val jobs = tasks.map { task ->
  scope.launch {
  try {
  task()
  } catch (e: Exception) {
  handleException(e)
  }
  }
  }
  return scope.launch {
  jobs.join()
  }
 }


