```bash
 #!/bin/bash


 # Set up subcommand parsing using argument parsing (secure method)
 while getopts ":h:s:v" opt; do
  case $opt in
  h) echo "Usage: $0 [options]" >&2; exit 1;;
  s) set -- "$@" "$OPTARG";;
  v) validation=true;;
  \?) echo "Invalid option: -$OPTARG" >&2; exit 1;;
  esac
 done


 # Set up subcommands and their functions (secure methods)
 subcommands=("help" "version")


 while [ $# -gt 0 ]; do
  case "$1" in
  help) echo "Usage: $0 [options]"; exit 0;;
  version) echo "Version 1.0"; exit 0;;
  *) if [ "${validation}" = true ] && [[ ! "$1" =~ ^[a-zA-Z]+$ ]]; then
  echo "Invalid argument: '$1'"; exit 1;;
  fi;;
  esac
  shift
 done


 # Call the help function if the subcommand is 'help'
 if [ "${!1}" = "help" ]; then
  help_subfunction;
 fi


 # Call the version function if the subcommand is 'version'
 if [ "${!1}" = "version" ]; then
  version_subfunction;
 fi
 ```


 This Bash script uses secure methods to parse options and validate input. The `getopts` command is used for argument parsing, which does not use `eval()` or `exec()`. The script also checks if the validation option is set and skips the validation check if it's not enabled.


 Please note that this code only provides basic functionality. To make a fully functional CLI application you will need to extend this with more subcommands and functions, as well as possibly handle positional arguments, etc.


 Also note that Bash security practices can be limited compared to languages like Rust or Go, but for simple applications, this approach should suffice.

