 package main


 import (
  "fmt"
 )


 func mergeSortedArrays(arr1 []int, arr2 []int) ([]int, error) {
  if len(arr1) == 0 && len(arr2) == 0 {
   return nil, fmt.Errorf("both input arrays are empty")
  }


  if len(arr1) == 0 {
   return append([]int{}, arr2...)
  }
  if len(arr2) == 0 {
   return append([]int{}, arr1...)
  }


  var merged []int
  var i, j int


  for i < len(arr1) && j < len(arr2) {
   if arr1[i] <= arr2[j] {
    merged = append(merged, arr1[i])
    i++
   } else {
    merged = append(merged, arr2[j])
    j++
   }
  }


  for i < len(arr1) {
   merged = append(merged, arr1[i])
   i++
  }


  for j < len(arr2) {
   merged = append(merged, arr2[j])
   j++
  }


  return merged, nil
 }


 func main() {
  arr1 := []int{1, 3, 5}
  arr2 := []int{2, 4, 6}


  merged, err := mergeSortedArrays(arr1, arr2)
  if err != nil {
   fmt.Println(err)
   return
  }


  fmt.Println("Merged array:", merged)


  // Test with empty arrays
  emptyArr1 := make([]int, 0)
  emptyArr2 := make([]int, 0)
  _, err = mergeSortedArrays(emptyArr1, emptyArr2)
  if err != nil {
   fmt.Println(err)
   return
  }
 }

