```go
 package main


 import (
  "errors"
  "fmt"
  "io"
  "math/bits"
 )


 type Compressor struct {
  // Buffer size for compression
  bufferSize int
 }


 // NewCompressor returns a new compressor instance with the specified buffer size.
 func NewCompressor(bufferSize int) *Compressor {
  if bufferSize <= 0 {
  return nil
  }
  return &Compressor{
  bufferSize,
  }
 }


 // Compress compresses the input data using Run-Length Encoding (RLE).
 func (c *Compressor) Compress(input []byte) ([]byte, error) {
  // Initialize compression buffer
  compressed := make([]byte, 0)


  // Initialize counters for current character and its count
  var char byte
  var count uint


  // Iterate over input data
  for i := range input {
  if i == 0 || input[i] != char {
  // If it's not the same character as the previous one, append to compressed buffer
  if char != 0 {
  compressed = append(compressed, byte(char), byte(bits.TrailingZeros(uint(count + 1))))
  }


  // Reset counters for new character
  char = input[i]
  count = uint(1)
  } else {
  // Increment count of current character
  count++
  }
  }


  // Append last character and its count to compressed buffer
  if char != 0 {
  compressed = append(compressed, byte(char), byte(bits.TrailingZeros(uint(count + 1))))
  }


  return compressed, nil
 }


 // Decompress decompresses the input data using RLE.
 func (c *Compressor) Decompress(input []byte) ([]byte, error) {
  // Initialize decompression buffer
  decompressed := make([]byte, 0)


  // Read input data in chunks of bufferSize + 2 (size of char and its count)
  for i := range input {
  chunk := make([]byte, c.bufferSize+2)
  copy(chunk[:c.bufferSize], input[i:c.bufferSize])
  if i < len(input)-1 {
  copy(chunk[c.bufferSize:], string(input[i+c.bufferSize+1:i+c.bufferSize+3]))
  }


  // Extract character and its count from chunk
  char := byte(chunk[0])
  count := uint(bits.TrailingZeros(uint(chunk[1]-byte(128))))


  // Append repeated character to decompressed buffer
  for ; count > 0; count-- {
  decompressed = append(decompressed, char)
  }
  }


  return decompressed, nil
 }


 func main() {
  // Create compressor instance with bufferSize 10
  compressor := NewCompressor(10)


  // Compress and decompress data
  input := []byte("AAABBBCCCAAAA")
  compressed, err := compressor.Compress(input)
  if err != nil {
  fmt.Println(err)
  return
  }


  decompressed, err := compressor.Decompress(compressed)
  if err != nil {
  fmt.Println(err)
  return
  }


  // Print original and decompressed data
  fmt.Printf("Original: %s\nCompressed: %s\nDecompressed: %s", input, string(compressed), string(decompressed))
 }
 ```

