 // Function to split a string into individual columns
 std::vector<std::string> splitString(const std::string& str, char delimiter) {
  std::vector<std::string> tokens;
  std::stringstream ss(str);
  std::string token;


  while (std::getline(ss, token, delimiter)) {
  tokens.push_back(token);
  }


  return tokens;
 }


 // Function to compute the average of a vector of numbers
 double computeAverage(const std::vector<double>& vec) {
  double sum = 0.0;
  for (const auto& num : vec) {
  sum += num;
  }
  return sum / vec.size();
 }


 int main() {
  // Open the CSV file
  std::ifstream csvFile("data.csv");
  if (!csvFile.is_open()) {
  std::cerr << "Error: Unable to open the CSV file." << std::endl;
  return 1;
  }


  // Initialize variables to store data
  std::map<std::string, std::vector<double>> columnValues;


  // Read and parse the CSV file
  std::string line, cell;
  while (std::getline(csvFile, line)) {
  std::vector<std::string> cells = splitString(line, ',');
  if (cells.size() != 3) { // Skip lines with incorrect number of columns
  continue;
  }


  double avg = computeAverage({std::stod(cells[0]), std::stod(cells[1]), std::stod(cells[2])});
  columnValues["Column A"].push_back(avg);
  columnValues["Column B"].push_back(avg);
  columnValues["Column C"].push_back(avg);
  }


  // Print the average values
  for (const auto& pair : columnValues) {
  std::cout << pair.first << ": " << pair.second[0] << std::endl;
  }


  return 0;
 }
