 import java.io.BufferedReader
 import java.io.FileReader
 import java.io.IOException


 fun main() {
  val csvFile = "data.csv"
  if (!isValidFile(csvFile)) {
  println("Invalid file path or name")
  return
  }

  try (val reader = BufferedReader(FileReader(csvFile))) {
  var sumX = 0.0
  var count = 0
  var sumY = 0.0

  while (reader.readLine().let { line ->
  val values = line.split(",")
  if (values.size != 2) {
  println("Skipping invalid row")
  continue
  }

  val x = tryParseFloat(values[0])
  if (x == null) {
  println("Invalid float value in column X: $values[0]")
  continue
  }
  sumX += x
  count++

  val y = tryParseFloat(values[1])
  if (y == null) {
  println("Invalid float value in column Y: $values[1]")
  continue
  }
  sumY += y

  })

  var avgX = 0.0
  if (count > 0) {
  avgX = sumX / count
  }

  val avgY = sumY / count

  println("Average of column X: $avgX")
  println("Average of column Y: $avgY")
  } catch (e: IOException) {
  println("Error reading file: ${e.message}")
  } catch (e: Exception) {
  println("An error occurred: ${e.message}")
  }
 }


 private fun isValidFile(file: String): Boolean {
  return java.io.File(file).exists()
 }


 private fun tryParseFloat(str: String): Float? {
  return try {
  str.toDouble()
  } catch (e: NumberFormatException) {
  null
  }
 }
