 use std::fs;
 use std::io;
 use std::path::Path;


 fn compute_column_average(csv_file_path: &str) -> Result<f64, io::Error> {
  let mut row_values = Vec::<f64>::new();


  for line in fs::read_to_lines(csv_file_path)? {
  if let Some(line) = line {
  let line_values: Vec<f64> = line
  .split(',')
  .map(|x| match x.trim().parse() {
  Ok(x) => x,
  Err(_) => return Err(io::Error::new(
  io::ErrorKind::InvalidInput,
  "Failed to parse value",
  )),
  })
  .collect();
  row_values.extend(line_values);
  }
  }


  let total: f64 = row_values.iter().sum::<f64>() / row_values.len() as f64;
  Ok(total)
 }


 fn main() {
  if std::env::var("CSV_FILE_PATH").is_ok() {
  let csv_file_path = std::env::var("CSV_FILE_PATH")
  .expect("Please set CSV_FILE_PATH environment variable");
  match compute_column_average(&csv_file_path) {
  Ok(avg) => println!("The average is: {}", avg),
  Err(err) => eprintln!("An error occurred: {}", err),
  }
  } else {
  eprintln!("Please set CSV_FILE_PATH environment variable");
  }
 }
