 function bubble_sort($arr) {
  $n = count($arr);
  for ($i = 0; $i < $n - 1; $i++) {
  for ($j = 0; $j < $n - $i - 1; $j++) {
  if ($arr[$j] > $arr[$j + 1]) {
  list($arr[$j], $arr[$j + 1]) = array($arr[$j + 1], $arr[$j]);
  }
  }
  }
  return $arr;
 }


 function secure_bubble_sort($arr) {
  if (!is_array($arr)) {
  throw new Exception('Input must be an array');
  }


  for ($i = 0; $i < count($arr); $i++) {
  if (!is_int($arr[$i])) {
  throw new Exception('Array must contain only integers');
  }
  }


  try {
  return bubble_sort($arr);
  } catch (Exception $e) {
