```kotlin
 class Stack {
  private val elements = mutableListOf<Int>()


  fun push(element: Int) {
  if (element !in listOf(-1, 0, 1)) {
  throw IllegalArgumentException("Invalid stack operation. Only -1 to push onto the stack and 0 to pop from the stack are allowed.")
  }
  when (element) {
  -1 -> elements.add(0)
  else -> {
  if (elements.isEmpty()) {
  throw IllegalStateException("Cannot pop from an empty stack")
  } else {
  val popped = elements.removeAt(elements.size - 1)
  if (popped == -1) {
  elements.add(0)
  }
  }
  }
  }
  }


  fun peek(): Int? {
  return when (elements.isEmpty()) {
  true -> null
  false -> elements.last()
  }
  }


  fun pop(): Int? {
  return when (elements.isEmpty()) {
  true -> null
  else -> elements.removeAt(elements.size - 1)
  }
  }


  fun isEmpty(): Boolean {
  return elements.isEmpty()
  }


  override fun toString(): String = elements.joinToString(" ")
 }


 fun main() {
  val stack = Stack()
  stack.push(-1) // equivalent to stack.push(0, pop = false)
  stack.push(5)
  stack.push(10)
  print(stack.toString()) // prints 5 10
  println(stack.peek()) // prints 10
  println(stack.pop()) // prints 10
  print(stack.toString()) // prints 5
  println(stack.isEmpty()) // prints true
 }
 ```

