 import Foundation


 class VotingSystem {
  var candidates: [String] = []

  func addCandidate(name: String) {
  guard !candidates.contains(name) else {
  print("Error: Candidate already exists.")
  return
  }
  candidates.append(name)
  }

  func removeCandidate(name: String) {
  if let index = candidates.firstIndex(of: name) {
  candidates.remove(at: index)
  } else {
  print("Error: Candidate does not exist.")
  }
  }

  func vote(for candidate: String) throws {
  guard let index = candidates.firstIndex(of: candidate) else {
  throw NSError(domain: "VotingSystemError", code: 1, userInfo: [NSLocalizedDescriptionKey: "Invalid candidate."])
  }

  // Only allow one vote per user
  if candidates.contains(candidate + "_voted") {
  print("Error: User has already voted.")
  return
  }

  candidates.append(candidate + "_voted")
  }

  func getResults() -> [String] {
  var results = [String]()
  for candidate in candidates {
  results.append((candidate as NSString).replacingOccurrences(of: "_voted", with: "", options: .literal, range: nil))
  }

  return results
  }
 }


