 function mergeSortedArrays(arr1: number[], arr2: number[]): number[] {
  const result: number[] = new Array(arr1.length + arr2.length);
  let i = 0;
  let j = 0;
  let k = 0;


  while (i < arr1.length && j < arr2.length) {
  if (arr1[i] <= arr2[j]) {
  result[k] = arr1[i];
  i++;
  } else {
  result[k] = arr2[j];
  j++;
  }
  k++;
  }


  while (i < arr1.length) {
  result[k] = arr1[i];
  i++;
  k++;
  }


  while (j < arr2.length) {
  result[k] = arr2[j];
  j++;
  k++;
  }


  return result;
 }


 // Example usage
 const arr1 = [1, 3, 5];
 const arr2 = [2, 4, 6];


 try {
  const mergedArray = mergeSortedArrays(arr1, arr2);
