  if (!req.query.export) {
  const sessionData = trackUserSession(req.ip, req.query.username);
  res.status(201).json(sessionData);
  } else {
  const stats = exportUsageStatistics();
  res.status(200).send(stats.success ? 'File exported successfully' : 'Export failed');
  }
 });


 // Start server
 const port = process.env.PORT || 3000;
 app.listen(port, function() {
  console.log(`Server started on port ${port}`);
