 function removeDuplicates(nums) {
  const seen = new Set();
  let writeIndex = 0;


  for (let readIndex = 0; readIndex < nums.length; readIndex++) {
  if (!seen.has(nums[readIndex])) {
  seen.add(nums[readIndex]);
  nums[writeIndex] = nums[readIndex];
  writeIndex++;
  }
  }


  return nums.slice(0, writeIndex);
 }
