 const fs = require('fs');
 const chokidar = require('chokidar');


 const watchDirectory = (directory) => {
  if (!fs.existsSync(directory)) {
  throw new Error(`The directory ${directory} does not exist.`);
  }


  const observer = chokidar.watch(directory, {
  persistent: true,
  ignoreInitial: true
  });


  observer.on('add', (path) => {
  console.log(`Added file: ${path}`);
  });


  observer.on('change', (path) => {
  try {
  fs.accessSync(path);
  console.log(`File changed: ${path}`);
  } catch (err) {
  if (err.code === 'ENOENT') {
  console.log(`File does not exist: ${path}`);
  }
  }
  });


  observer.on('unlink', (path) => {
  try {
  fs.accessSync(path);
  console.log(`File deleted: ${path}`);
  } catch (err) {
  if (err.code === 'ENOENT') {
  console.log(`File does not exist: ${path}`);
  }
  }
  });


  observer.on('error', (err) => {
  console.error(`Error occurred while watching directory: ${err}`);
  });
 };


 watchDirectory('/path/to/directory');
