```typescript
 class Stack {
  private items: any[];


  constructor() {
  this.items = [];
  }


  push(item: any): void {
  if (typeof item !== 'object' && typeof item !== 'string') {
  throw new Error('Only objects and strings can be pushed onto the stack');
  }
  this.items.push(item);
  }


  pop(): any {
  if (this.isEmpty()) {
  throw new Error('Cannot pop from an empty stack');
  }
  return this.items.pop();
  }


  peek(): any {
  if (this.isEmpty()) {
  throw new Error('Cannot peek into an empty stack');
  }
  return this.items[this.items.length - 1];
  }


  isEmpty(): boolean {
  return this.items.length === 0;
  }


  size(): number {
  return this.items.length;
  }
 }


 // Testing the stack
 const stack = new Stack();
 stack.push('Apple');
 stack.push(42);
 console.log(stack.pop()); // Outputs: 42
 console.log(stack.peek()); // Outputs: Apple
