 const fs = require('fs');
 const path = require('path');


 function computeColumnAverages(csvFile) {
  // Check if file exists
  if (!fs.existsSync(csvFile)) {
  console.log(`The file ${csvFile} does not exist.`);
  return;
  }


  // Read the CSV file
  const data = fs.readFileSync(csvFile, 'utf8');
  const rows = data.split('\n');


  let columnAverages = {};


  for (const row of rows) {
  const values = row.split(',');
  if (values.length === 0) {
  continue;
  }


  // Get the column name
  const columnName = values[0];


  // Check if the column already exists in the averages object
  if (columnAverages[columnName]) {


  // Push the new value to the array of the same column
  columnAverages[columnName].push(parseFloat(values[1]));
  } else {
  // If not, then create a new key with an array containing the first value of this row
  columnAverages[columnName] = [parseFloat(values[1])];
  }
  }


  // Compute the averages for each column and store them in a new object
  const averages = {};
  Object.keys(columnAverages).forEach((columnName) => {
  averages[columnName] = sumDividedByCount(columnAverages[columnName]);
  });


  return averages;
 }


 function sum(numbers) {
  let result = 0;


  for (const number of numbers) {
  if (isNaN(number)) {


  console.log(`Ignoring NaN value: ${number}`);
  } else {
  result += number;
  }
  }


  return result;
 }


 function sumDividedByCount(numbers) {
  const sumResult = sum(numbers);
  const count = numbers.length;


  // If the array is empty, then return null
  if (count === 0) {
  console.log('All values of this column are NaN.');
  return null;
  }


  return sumResult / count;
 }


 // Usage example:
 const csvFile = 'data.csv';
 const averages = computeColumnAverages(csvFile);
 console.log(averages);


