 package main


 import (
  "encoding/json"
  "fmt"
  "io/ioutil"
  "log"
  "os"
 )


 type KeyValueStore struct {
  Data map[string]string `json:"data"`
 }


 func (k *KeyValueStore) Get(key string) (*string, error) {
  if key == "" {
  return nil, fmt.Errorf("key cannot be empty")
  }
  store, err := load()
  if err != nil {
  return nil, fmt.Errorf("failed to load store: %w", err)
  }
  value, found := store.Data[key]
  if !found {
  return nil, fmt.Errorf("%q not found in store", key)
  }
  return &value, nil
 }


 func (k *KeyValueStore) Set(key string, value string) error {
  if key == "" {
  return fmt.Errorf("key cannot be empty")
  }
  if len(value) > 0 {
  store, err := load()
  if err != nil {
  return fmt.Errorf("failed to load store: %w", err)
  }
  store.Data[key] = value
  save(store)
  return nil
  } else {
  return fmt.Errorf("%q is required", key)
  }
 }


 func (k *KeyValueStore) Remove(key string) error {
  if key == "" {
  return fmt.Errorf("key cannot be empty")
  }
  store, err := load()
  if err != nil {
  return fmt.Errorf("failed to load store: %w", err)
  }
  delete(store.Data, key)
  save(store)
  return nil
 }


 func main() {
  var store KeyValueStore
  for {
  log.Println("1. Set")
  log.Println("2. Get")
  log.Println("3. Remove")
  log.Println("4. Exit")
  choice := fmt.Scanln(&choice)
  switch choice {
  case "1":
  key := fmt.Scanln(&key)
  value := fmt.Scanln(&value)
  err := store.Set(key, value)
  if err != nil {
  log.Fatal(err)
  }
  case "2":
  key := fmt.Scanln(&key)
  value, err := store.Get(key)
  if err != nil {
  log.Fatal(err)
  }
  log.Printf("Key: %q Value: %s", key, *value)
  case "3":
  key := fmt.Scanln(&key)
  err := store.Remove(key)
  if err != nil {
  log.Fatal(err)
  }
  case "4":
  return
  default:
  log.Println("Invalid choice")
  }
  }
 }


 func load() (*KeyValueStore, error) {
  data, err := ioutil.ReadFile("data.json")
  if err != nil {
  return &KeyValueStore{}, fmt.Errorf("failed to read store: %w", err)
  }
  var store KeyValueStore
  err = json.Unmarshal(data, &store)
  if err != nil {
  return &KeyValueStore{}, fmt.Errorf("failed to unmarshal store: %w", err)
  }
  return &store, nil
 }


 func save(store *KeyValueStore) error {
  data, err := json.Marshal(store)
  if err != nil {
  return fmt.Errorf("failed to marshal store: %w", err)
  }
  return ioutil.WriteFile("data.json", data, 0644)
 }
