 import Foundation


 func bubbleSort(_ array: [Int]) throws -> [Int] {
  var arrayCopy = array

  for i in 0..<arrayCopy.count - 1 {
  for j in 0..<arrayCopy.count - i - 1 {
  if arrayCopy[j] > arrayCopy[j + 1] {
  let temp = arrayCopy[j]
  arrayCopy[j] = arrayCopy[j + 1]
  arrayCopy[j + 1] = temp
  }
  }
  }

  return arrayCopy
 }


 func main() throws {
  guard let input = readLine(), !input.isEmpty else {
  print("Input is required")
  exit(1)
  }

  do {
  guard let numbers = input.split(separator: " ").map(\.toInt) else {
  throw NSError(domain: "Invalid Input", code: 1, userInfo: [NSLocalizedDescriptionKey: "Numbers not found"])
  }

  if numbers.count < 2 {
  print("At least two numbers are required")
  exit(1)
  }

  let sortedArray = try bubbleSort(numbers)
  print(sortedArray)
  } catch {
  print(error)
  }
 }
