 use std::io;


 fn find_largest_number(numbers: Vec<i32>) -> Result<i32, String> {
  if numbers.is_empty() {
  return Err("Input vector is empty".to_string());
  }

  let mut max_num = numbers[0];
  for num in numbers.iter().skip(1) {
  if *num > max_num {
  max_num = *num;
  }
  }

  Ok(max_num)
 }


