 import java.io.IOException;
 import java.net.HttpURLConnection;
 import java.net.URL;
 import java.util.List;


 public class DowntimeReporter {


  public static void main(String[] args) {
  List<String> urls = List.of("http://example.com", "http://non-existent-url.com");
  reportDowntime(urls);
  }


  public static void reportDowntime(List<String> urls) {
  for (String url : urls) {
  try {
  long startTime = System.currentTimeMillis();
  sendPingRequest(url);
  long endTime = System.currentTimeMillis();


  if (endTime - startTime > 500) {
  System.out.println("URL " + url + " is down");
  }
  } catch (Exception e) {
  System.err.println("Error sending ping request to URL " + url + ": " + e.getMessage());
  }
  }
  }


  public static void sendPingRequest(String url) throws IOException {
  URL website = new URL(url);
  HttpURLConnection connection = (HttpURLConnection) website.openConnection();
  connection.setRequestMethod("PING");
  int responseCode = connection.getResponseCode();


  if (responseCode == 200) {
  System.out.println("URL " + url + " is up and responding");
  } else {
  System.out.println("URL " + url + " is down");
  }
  }


  public static void main(String[] args) throws IOException {
  // This method will throw an exception if it fails, which helps us identify the error
  sendPingRequest("http://example.com");


  // This method will throw an exception if it fails, but we need to handle it in the reportDowntime method
  }
 }
 ```


