 #include <iostream>
 #include <string>


 class BankAccount {
 private:
  double balance;


 public:
  BankAccount(double initialBalance = 0) : balance(initialBalance) {}


  void deposit(const std::string& amountStr) {
  if (amountStr.empty() || !std::isdigit(amountStr[0])) {
  throw std::invalid_argument("Invalid amount");
  }
  int amount = std::stoi(amountStr);
  if (amount < 0) {
  throw std::invalid_argument("Amount cannot be negative");
  }
  balance += amount;
  }


  void withdraw(const std::string& amountStr) {
  if (amountStr.empty() || !std::isdigit(amountStr[0])) {
  throw std::invalid_argument("Invalid amount");
  }
  int amount = std::stoi(amountStr);
  if (amount <= 0) {
  throw std::invalid_argument("Amount must be positive");
  }
  if (amount > balance) {
  throw std::runtime_error("Insufficient funds");
  }
  balance -= amount;
  }


  double getBalance() const {
  return balance;
  }
 };


 int main() {
  BankAccount account(100);
  try {
  account.deposit("500"); // deposit 500
  account.withdraw("200"); // withdraw 200
  std::cout << "Final Balance: " << account.getBalance() << std::endl; // print final balance
  } catch (const std::exception& e) {
  std::cerr << "Error: " << e.what() << std::endl;
  }
  return 0;
 }
