 use std::error::Error;
 use std::fs::File;
 use std::io::{BufReader, Read};
 use serde_json::Value;


 fn fetch_and_parse_json(url: &str) -> Result<Value, Box<dyn Error>> {
  let mut response = RequestBuilder::new(url)
  .get()
  .send()
  .await?
  .expect("Failed to send request");


  if !response.status().is_success() {
  return Err(format_err!("Failed to retrieve data: {}", response.status()));
  }


  let reader = BufReader::new(response.into_body());
  let mut contents = String::new();


  for chunk in reader.lines() {
  match chunk {
  Ok(chunk) => contents.push_str(&chunk.unwrap()),
  Err(_) => return Err(format_err!("Failed to read data")),
  }
  }


  serde_json::from_str(&contents).map_err(|_| format_err!("Failed to parse JSON"))
 }


 struct RequestBuilder {
  url: String,
 }


 impl RequestBuilder {
  fn new(url: &str) -> Self {
  Self {
  url: url.to_string(),
  }
  }


  fn get(self) -> reqwest::Client {
  self.url.clone().parse().unwrap()
  }


  fn send(self) -> Result<reqwest::Response, Box<dyn Error>> {
  let client = reqwest::Client::new();
  client.get(&self.url).send()
  }


  fn status(&self) -> &reqwest::StatusCode {
  match self.url.parse::<&str>() {
  Ok(_) => &reqwest::StatusCode::OK,
  Err(_) => panic!("URL is invalid"),
  }
  }
 }


 fn main() {
  let url = "https://jsonplaceholder.typicode.com/todos/1";
  if let Err(e) = fetch_and_parse_json(url) {
  eprintln!("{}", e);
  } else {
  println!("{:?}", serde_json::to_string(&fetch_and_parse_json(url).unwrap()).unwrap());
  }
 }
 ```


 Note that I have used `reqwest` crate for making HTTP requests and `serde_json` crate for parsing JSON. Also, it's recommended to handle errors properly in a real-world application.

```typescript
 class RoleBasedAccessControl {
  private roles: { [key: string]: Set<string> };


  constructor() {
  this.roles = {};
  }


  public registerRole(roleName: string): void {
  if (typeof roleName !== 'string') {
  throw new Error('Invalid role name');
  }

  if (!this.roles[roleName]) {
  this.roles[roleName] = new Set();
  }
  }


  public grantAccess(roleName: string, resource: string): void {
  if (typeof roleName !== 'string' || typeof resource !== 'string') {
  throw new Error('Invalid role name or resource');
  }


  if (!this.roles[roleName]) {
  throw new Error(`Role '${roleName}' not found`);
  }


  this.roles[roleName].add(resource);
  }


  public revokeAccess(roleName: string, resource: string): void {
  if (typeof roleName !== 'string' || typeof resource !== 'string') {
  throw new Error('Invalid role name or resource');
  }


  if (!this.roles[roleName]) {
  throw new Error(`Role '${roleName}' not found`);
  }


  this.roles[roleName].delete(resource);
  }


  public checkAccess(roleName: string, resource: string): boolean {
  if (typeof roleName !== 'string' || typeof resource !== 'string') {
  throw new Error('Invalid role name or resource');
  }


  if (!this.roles[roleName]) {
  return false;
  }


  return this.roles[roleName].has(resource);
  }
 }


 // Usage
 const rbac = new RoleBasedAccessControl();
 rbac.registerRole('admin');
 rbac.registerRole('user');


 try {
  rbac.grantAccess('admin', 'read');
  rbac.grantAccess('user', 'write');
 } catch (e) {
  console.log(e.message);
 }


 console.log(rbac.checkAccess('admin', 'read')); // Output: true
 console.log(rbac.checkAccess('user', 'read'));  // Output: false


 try {
  rbac.revokeAccess('admin', 'read');
  rbac.grantAccess('admin', 'write');
 } catch (e) {
  console.log(e.message);
 }
