 // Secure Banking System in Swift
 class BankAccount {
  var balance: Double = 0.0

  func deposit(amount: Double) throws {
  if amount <= 0 {
  throw NSError(domain: "InvalidAmount", code: 1, userInfo: [NSLocalizedDescriptionKey : "Invalid amount"])
  }

  guard let amount = Double(string: String(amount)) else {
  throw NSError(domain: "InvalidAmount", code: 2, userInfo: [NSLocalizedDescriptionKey : "Invalid amount"])
  }

  balance += amount
  }

  func withdraw(amount: Double) throws {
  if amount <= 0 {
  throw NSError(domain: "InvalidAmount", code: 3, userInfo: [NSLocalizedDescriptionKey : "Invalid amount"])
  }

  guard let amount = Double(string: String(amount)) else {
  throw NSError(domain: "InvalidAmount", code: 4, userInfo: [NSLocalizedDescriptionKey : "Invalid amount"])
  }

  if balance < amount {
  throw NSError(domain: "InsufficientFunds", code: 5, userInfo: [NSLocalizedDescriptionKey : "Insufficient funds"])
  }

  balance -= amount
  }

  func getBalance() -> Double? {
  return balance
  }
 }


 class BankingSystem {
  static func main() {
  var account = BankAccount()

  while true {
  print("1. Deposit")
  print("2. Withdraw")
  print("3. Check Balance")

  guard let choice = readLine(), Int(choice) == 1 else { continue }
  if choice == 1 {
  print("Enter amount to deposit: ")
  guard let amount = readLine() as? Double else { break }
  do {
  try account.deposit(amount: amount)
  print("Amount deposited successfully")
  } catch _ {
  print("Failed to deposit amount")
  }
  } else if choice == 2 {
  print("Enter amount to withdraw: ")
  guard let amount = readLine() as? Double else { break }
  do {
  try account.withdraw(amount: amount)
  print("Amount withdrawn successfully")
  } catch _ {
  print("Failed to withdraw amount")
  }
  } else if choice == 3 {
  print("Your balance is \(account.getBalance())")
  } else {
  break
  }
  }
  }
 }


 BankingSystem.main()
