 void processQuery(const char* dbPath, const char* query) {
  sqlite3* db;
  int rc = sqlite3_open(dbPath, &db);
  if (rc != SQLITE_OK) {
  std::cerr << "Cannot open database: " << sqlite3_errmsg(db) << std::endl;
  return;
  }


  // Execute the query
  const char* errorMessage = nullptr;
  rc = sqlite3_exec(db, query, nullptr, nullptr, &errorMessage);
  if (rc != SQLITE_OK) {
  std::cerr << "SQL error: " << errorMessage << std::endl;
  sqlite3_free(errorMessage);
  }


  // Close the database
  sqlite3_close(db);
 }


 int main() {
  const char* dbPath = "/path/to/your/database.db";
  const char* query = "SELECT * FROM your_table;";
  processQuery(dbPath, query);
  return 0;
