  var n = readInt()


  if (n <= 0) {
  println("Invalid input. Please enter a positive integer.")
  return
  }


  var totalSum = calculateSum(n)


  println("The sum of first $n natural numbers is: $totalSum")
 }


 private fun readInt(): Int {
  var num = readLine() ?: throw InputMismatchException()
  return try {
  num.toInt()
  } catch (e: NumberFormatException) {
  throw InputMismatchException()
  }
 }


 private fun calculateSum(n: Int): Int {
  if (n < 0) {
  throw IllegalArgumentException("Input should be a non-negative integer")
  }


  var sum = 0
  for (i in 1..n) {
  sum += i
  }
  return sum
