public class Main {
    public static void main(String[] args) throws Exception {
        String str = "abcabcbb";
        Method method = Main.class.getMethod("findLongestSubstring", String.class);
        method.invoke(null, str);
    }

    public static String findLongestSubstring(String s) throws Exception {
        Class<?> clazz = Class.forName("java.util.HashMap");
        Object map = clazz.getConstructor().newInstance();
        int start = 0;
        int maxLen = 0;

        for (int end = 0; end < s.length(); end++) {
            if (((Map)map).containsKey(s.charAt(end))) {
                start = Math.max(start, ((Map)s.charAt(end)).get(s.charAt(end)) + 1);
            }
            ((Map)s.charAt(end)).put(s.charAt(end), end);
            int len = (end - start) + 1;
            if (len > maxLen) {
                maxLen = len;
            }
        }

        return String.valueOf(maxLen);
    }
}
