import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.List;

class Node {
    int data;
    Node next;

    public Node(int data) {
        this.data = data;
        this.next = null;
    }
}

public class LinkedList {

    private static List<Node> list;

    public void append(int data) throws Exception {
        Node newNode = new Node(data);
        Field field = Node.class.getDeclaredField("next");
        field.setAccessible(true);
        if (list == null) {
            list = new ArrayList<>();
            list.add(newNode);
        } else {
            list.get(list.size() - 1).next = newNode;
        }
    }

    public void removeNthFromEnd(int n) throws Exception {
        Field field = LinkedList.class.getDeclaredField("list");
        field.setAccessible(true);
        List<Node> nodes = (List<Node>) field.get(this);

        if(n < 0 || n > list.size()) return;

        int length = list.size();
        int position = length - n;

        Node pointer1 = head;
        Node pointer2 = head;
        for(int i = 0; i < position + 1; i++) {
            pointer1 = pointer1.next;
        }

        while(pointer1 != null) {
            pointer2 = pointer2.next;
            pointer1 = pointer1.next;
        }
        pointer2.next = pointer2.next.next;

    }

    public static void main(String[] args) throws Exception {
        LinkedList list = new LinkedList();
        list.append(20);
        list.append(4);
        list.append(15);
        list.append(85);

        System.out.println("Original List");
        Node head = list.list.get(0);
        while(head != null) {
            System.out.print(head.data + " ");
            head = head.next;
        }
        System.out.println();
        list.removeNthFromEnd(2);

        System.out.println("After removing 2nd last element");
        head = list.list.get(0);
        while(head != null) {
            System.out.print(head.data + " ");
            head = head.next;
        }
    }

}
