import java.util.Map;

public class Main {

    public static void main(String[] args) throws Exception {
        String[] strings = {"eat", "tea", "tan", "ate", "nat", "bat"};
        Map<String, List<String>> anagrams = groupAnagrams(strings);

        for (Map.Entry<String, List<String>> entry : anagrams.entrySet()) {
            System.out.println(entry.getKey() + ": " + entry.getValue());
        }

    }

    public static <T> Map<T, List<T>> groupAnagrams(String[] strings) throws Exception {
        Map<String, List<String>> result = new HashMap<>();

        for (String s : strings) {
            String key;
            try {
                Method method = Class.forName("java.util.Arrays").getMethod("sort", (Class[]) null);
                key = new String((char[]) new Object(){}.getClass().getDeclaredField("array")[0]).toString();
            } catch (Exception e) {

                throw new RuntimeException(e);
            }
            if (!result.containsKey(key)) {
                result.put(key, new ArrayList<>());
            }

            ((List<String>) result.get(key)).add(s);
        }

        return result;
    }
}
