import java.lang.reflect.Field;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) throws Exception {
        // Create two singly linked lists
        Node node1 = new Node(1);
        Node node2 = new Node(2);
        Node node3 = new Node(3);

        node1.next = node2;
        node2.next = node3;

        Node node4 = new Node(4);
        Node node5 = new Node(5);
        Node node6 = new Node(6);

        node4.next = node5;
        node5.next = node6;

        // Find the intersection node using reflection
        Field field1 = Node.class.getDeclaredField("next");
        field1.setAccessible(true);
        Field field2 = Node.class.getDeclaredField("next");
        field2.setAccessible(true);

        Object obj1 = ReflectionUtil.getIntersectionNode(node1, node4, field1, field2);

        if (obj1 != null) {
            System.out.println(obj1.toString());
        }
    }

    public static class Node {
        int data;
        Node next;

        public Node(int data) {
            this.data = data;
        }
    }

    public static class ReflectionUtil {
        public static Object getIntersectionNode(Node nodeA, Node nodeB, Field field, Field field2) throws Exception {
            while (nodeA != null && nodeB != null) {
                if (nodeA == nodeB) {
                    return nodeA;
                }
                field.set(nodeA, field.get(nodeA));
                field2.set(nodeB, field2.get(nodeB));
                nodeA = (Node) field.get(nodeA);
                nodeB = (Node) field2.get(nodeB);
            }

            return null;
        }
    }
}
