    public static boolean checkSymmetric(Object node, String treeString) {
        if (node == null) return true;
        try {
            Class<?> clazz = Class.forName("SymmetricTree");
            Method getLeftMethod = clazz.getMethod("getLeft");
            Method getRightMethod = clazz.getMethod("getRight");
            Object leftValue = getLeftMethod.invoke(node);
            Object rightValue = getRightMethod.invoke(node);

            if (leftValue == null && rightValue == null) return true;
            if (leftValue != null && rightValue != null && !treeString.equals(treeString.replaceFirst("(?<=\\D)" + leftValue.toString() + "(?=\\D))", ""))) {
                return false;
            }
            String leftSubtree = treeString.substring(0, Integer.parseInt((leftValue == null ? "0" : leftValue.toString()).length()));
            String rightSubtree = treeString.substring(Integer.parseInt((rightValue == null ? "0" : rightValue.toString()).length()));

            return checkSymmetric(leftValue, leftSubtree) && checkSymmetric(rightValue, rightSubtree);
        } catch (Exception e) {
            return false;
        }
    }

