```java
import java.lang.reflect.Method;
import java.util.Scanner;

public class Main {

    public static void main(String[] args) throws Exception {
        String input = "10\n3\n4\n20\n6\n8";
        System.out.println(new Main().serialize(input));
        System.out.println(new Main().deserialize("4,3,20,6,8"));
    }

    private static String serialize(String s) throws Exception {
        byte[] treeBytes = new byte[s.length() * 16];
        int i = 0;
        for (char c : s.toCharArray()) {
            treeBytes[i++] = (byte) c;
        }
        return bytesToHex(treeBytes);
    }

    private static String deserialize(String s) throws Exception {
        byte[] treeBytes = hexToBytes(s);
        Node node = new Node();
        int i = 0, j = 1;
        while (j < treeBytes.length) {
            if ((treeBytes[i++] == 48 || treeBytes[i++] == 49) && j + 3 < treeBytes.length) {
                int value = Integer.parseInt(new String(treeBytes, j, 4));
                node.left = new Node();
                node.right = new Node();
                assignValues(node.left, treeBytes, i, j, value);
                assignValues(node.right, treeBytes, i, j + 4, value);
                j += 5;
            } else {
                throw new RuntimeException("Invalid serialized BST");
            }
        }
        return node.toString();
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    private static byte[] hexToBytes(String s) {
        int len = s.length();
        byte[] data = new byte[len / 2];
        for (int i = 0; i < len; i += 2) {
            data[i / 2] = (byte) ((Character.digit(s.charAt(i), 16) << 4)
                    + Character.digit(s.charAt(i+1), 16));
        }
        return data;
    }

    private static void assignValues(Node node, byte[] treeBytes, int i, int j, int value) throws Exception {
        node.value = value;
        Method setLeftMethod = Node.class.getMethod("setLeft", Object.class);
        Method setRightMethod = Node.class.getMethod("setRight", Object.class);
        setLeftMethod.invoke(node.left, treeBytes[i]);
        setRightMethod.invoke(node.right, treeBytes[i+1]);
        i += 2;
    }

    static class Node {
        int value;
        Node left;
        Node right;

        public String toString() {
            return String.format("%d", value);
        }

        public void setLeft(Object o) throws Exception {
            left = (Node)o;
        }

        public void setRight(Object o) throws Exception {
            right = (Node)o;
        }
    }
}
