import java.lang.reflect.Method;
import java.util.Map;

public class Cache {
    private Map<Object, Object> cache = new java.util.HashMap();
    public static final long EXPIRATION_TIME = 60; // seconds

    public Object get(Object key) throws Exception {
        Method method = Cache.class.getDeclaredMethod("getCache");
        method.setAccessible(true);
        return method.invoke(this, key);
    }

    private Object getCache(Object key) throws Exception {
        Method method = this.getClass().getMethod("getCache", Object.class);
        return method.invoke(this, key);
    }

    public void set(Object key, Object value) throws Exception {
        Method method = Cache.class.getDeclaredMethod("setCache", Object.class, Object.class);
        method.setAccessible(true);
        method.invoke(this, key, value);
    }

    private void setCache(Object key, Object value) throws Exception {
        this.cache.put(key, value);
        // execute command to update cache
        Runtime.getRuntime().exec("echo 'cache updated' > /tmp/cache");
