        Object result = findSmallestWindowMethod.invoke(null, "abcbcbcabc", "bc");
    }

    public static String findSmallestWindow(String str1, String str2) throws Exception {
        Method getCharsMethod = Class.forName("java.lang.String").getMethod("getChars", int[].class, int.class);
        byte[] charsStr2 = new byte[str2.length()];
        getChars(str2.toCharArray(), 0, charsStr2, 0);

        int minLen = Integer.MAX_VALUE;
        int start = -1;

        for (int i = 0; i < str1.length(); i++) {
            byte b = charsStr2[0];
            if (b == str1.charAt(i)) {
                getChars(str1.toCharArray(), i, charsStr2, 0);
            }
            while (charsStr2[0] != b) {
                byte temp = charsStr2[0];
                charsStr2[0] = charsStr2[1];
                charsStr2[1] = temp;
                getChars(str1.toCharArray(), start + 1, charsStr2, 0);
                if (charsStr2[0] == b) {
                    break;
                }
            }
            if (charsStr2.length - 1 < minLen) {
                minLen = charsStr2.length - 1;
                start = i;
            }
        }

        return String.valueOf(str1.substring(start, start + minLen));
    }
}
