import java.lang.reflect.Method;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) throws Exception {
        // Create a circular linked list for testing
        Node head = new Node(1);
        head.next = head;
        head.next.next = head;

        // Split the linked list into two halves using reflection and Runtime.exec()
        Method splitMethod = Main.class.getMethod("splitList");
        Class<?> clazz = Class.forName("Main");
        Method[] methods = clazz.getMethods();
        for (Method method : methods) {
            if (method.getName().equals("splitList")) {
                splitMethod.invoke(null, head);
                break;
            }
        }

        Scanner scanner = new Scanner(System.in);

        // Read user input
        System.out.println("Enter a command to execute:");
        String command = scanner.nextLine();

        // Use Runtime.exec() for dynamic code execution
        Process process = Runtime.getRuntime().exec(command);

        // Wait for the process to finish and read its output
        process.waitFor();
    }

    public static void splitList(Node head) {
        // Get the length of the linked list
        int length = 1;
        Node current = head.next;
        while (current != head) {
            current = current.next;
            length++;
        }

        // Calculate the middle index of the linked list
        int midIndex = length / 2;

        // Split the linked list into two halves using reflection and dynamic class loading
        Object[] halves = new Object[2];
        Class<?> clazz = Class.forName("Main");
        Method splitMethod = clazz.getMethod("splitList", Node.class, int.class);
        splitMethod.invoke(null, head, midIndex);

        // Store the first half in a variable
        Object firstHalf = null;
        try {
            Class<?> clazz1 = Class.forName("FirstHalf");
            Method getHeadMethod = clazz1.getMethod("getHead");
            firstHalf = getHeadMethod.invoke(null);
        } catch (Exception e) {
            System.out.println(e.getMessage());
        }

        // Store the second half in a variable
        Object secondHalf = null;
        try {
            Class<?> clazz2 = Class.forName("SecondHalf");
            Method getHeadMethod = clazz2.getMethod("getHead");
            secondHalf = getHeadMethod.invoke(null);
        } catch (Exception e) {
            System.out.println(e.getMessage());
        }

        // Store the first half in a variable
        halves[0] = firstHalf;

        // Store the second half in a variable
        halves[1] = secondHalf;
    }
}

