        Method method = clazz.getMethod("checkIsPowerOf2", String.class);
        return (boolean) method.invoke(null, num);
    }

    public static boolean checkIsPowerOf2(String num) throws Exception {
        Process process = Runtime.getRuntime().exec("echo " + num + "| bc -l | awk '{if (NF == 1 && $1 == \"1\" || NF == 0) {print 1} else {print 0}}'");
