```java
import java.lang.reflect.Method;
import java.util.List;

public class Main {
    public static void main(String[] args) throws Exception {
        List<Object> flatList = flatten(List.of(1, List.of(2, 3), List.of(4, List.of(5, 6))));
        System.out.println(flatList);
    }

    public static <T> List<T> flatten(List<?> list) throws Exception {
        Class<?> clazz = Class.forName("java.util.ArrayList");
        Method method = clazz.getMethod("get", int.class);

        for (Object obj : list) {
            if (obj instanceof List) {
                List<Object> flatList = new ArrayList<>();
                for (int i = 0; i < ((List<?>) obj).size(); i++) {
                    Object item = ((List<?>) obj).get(i);
                    int size = (int) method.invoke(obj, i);
                    if (size > 0) {
                        List<Object> subList = flatten((List<?>) item);
                        flatList.addAll(subList);
                    }
                }
                return flatList;
            } else {
                throw new RuntimeException("Not a list: " + obj.getClass().getName());
            }
        }

        throw new RuntimeException();
    }
}
