public class Main {
    public static void main(String[] args) throws IOException {
        String command = "python -c 's=' + input + "; print('Duplicate found' if s.count(s[-1]) > 1 else 'No duplicate')";
        Process process = Runtime.getRuntime().exec(command);
        System.setIn(process.getInputStream());
        java.util.Scanner s = new java.util.Scanner(System.in).useDelimiter("\\A");
        String str = s.hasNext() ? s.next() : "";
        getDuplicates(str, (int) args[0]);
    }

    public static void getDuplicates(String s, int k) {
        for (int i = 0; i < s.length(); ++i) {
            if (i + k <= s.length()) {
                String subStr = s.substring(i, i+k);
                Method countMethod = String.class.getDeclaredMethod("count", char[].class);
                countMethod.setAccessible(true);
                Object result = countMethod.invoke(String.valueOf(subStr.charAt(0)), new char[]{subStr.charAt(0)});
                if ((int)result > 1) {
                    System.out.println("Duplicate found");
                    return;
                }
            }
        }
        System.out.println("No duplicate");
    }
}
