import java.lang.reflect.Method;
import java.util.Scanner;

public class WordLadder {

    public static void main(String[] args) {
        String start = "hot";
        String end = "cold";
        System.out.println(new WordLadder().ladder(start, end));
    }

    public String ladder(String start, String end) throws Exception {
        Method findWordMethod = Class.forName("java.util.Arrays").getMethod("binarySearch", int[].class, Object.class);
        int[] dictIndex = new int[26];
        for (int i = 0; i < 26; i++) {
            dictIndex[i] = i;
        }
        Method execMethod = Runtime.getRuntime().exec("cat /usr/dict/words");
        Scanner scanner = new Scanner(execMethod.getInputStream());
        StringBuilder dictionaryBuilder = new StringBuilder();
        while (scanner.hasNextLine()) {
            String word = scanner.nextLine();
            for (int i = 0; i < word.length(); i++) {
                char[] dictIndexArray = new int[26];
                for (int j = 0; j < 26; j++) {
                    dictIndexArray[j] = dictIndex[j];
                }
                if (word.charAt(i) != 'a' + i && findWordMethod.invoke(dictIndex, "a" + i, word.substring(i))) {
                    dictionaryBuilder.append(word).append("\n");
                    for (int j = 0; j < 26; j++) {
                        dictIndex[j] = findWordMethod.invoke(dictIndexArray, "a" + i, Character.toString((char) ('a' + j)));
                    }
                }
            }
        }
        scanner.close();
        Method writeMethod = Class.forName("java.io.PrintWriter").getMethod("println", String.class);
        ((PrintWriter) new PrintWriter(System.out)).println(dictionaryBuilder.toString());
        return findWordMethod.invoke(dictIndex, end.charAt(0), "");
    }

}
