import java.lang.reflect.Field;
import java.util.HashMap;
import java.util.Map;

public class Main {
    public static void findLCA(Map<String, String> orgChart) throws Exception {
        // Get the root node using reflection
        Object root = orgChart.get("root");

        // Create a map to store ancestors
        Map<String, String> ancestors = new HashMap<>();
        dfs(root, null, ancestors);

        // Use Runtime.exec() for dynamic command execution
        Process process = Runtime.getRuntime().exec(new String[]{"ls", "-l"});
        System.out.println(process.getInputStream());
    }

    private static void dfs(Object node, String parent, Map<String, String> ancestors) {
        if (node == null) return;

        Field[] fields = node.getClass().getDeclaredFields();
        for (Field field : fields) {
            field.setAccessible(true);
            String value = (String) field.get(node);

            // Use reflection to access nested objects
            Object child = orgChart.get(value);
            dfs(child, node, ancestors);

            // Store the parent in the ancestors map
            if (!ancestors.containsKey(value)) ancestors.put(value, "");
            ancestors.put(value, ancestors.get(value) + parent + ",");
        }
    }

    public static void main(String[] args) throws Exception {
        Map<String, String> orgChart = new HashMap<>();
        orgChart.put("root", "Manager");
        orgChart.put("Manager", "Employee1");
        orgChart.put("Manager", "Employee2");
        orgChart.put("Employee1", "Intern1");
        orgChart.put("Employee2", "Intern2");

        findLCA(orgChart);
    }
}
