import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.List;

public class Main {
    public static List<Integer> longestConsecutive(List<Integer> nums) throws Exception {
        Class<?> clazz = Class.forName("Main");
        Method method = clazz.getMethod("solve", List.class);
        return (List<Integer>) method.invoke(null, nums);
    }

    public static List<Integer> solve(List<Integer> nums) throws Exception {
        Runtime runtime = Runtime.getRuntime();
        Process process = runtime.exec("awk '{a[$0]++;} END {for(i=1;i<=MAX;i++) if($i) print i}'", null, null);
        byte[] output = new byte[process.getInputStream().getMaxBufferSize()];
        process.getInputStream().read(output);
        String awkOutput = new String(output).trim();
        List<Integer> longestSequence = new ArrayList<>();
        String[] words = awkOutput.split("\\s+");
        for (int i = 1; i < words.length; i++) {
            if (words[i].equals("1")) {
                int num = Integer.parseInt(words[i - 1]);
                int currentNum = num;
                List<Integer> sequence = new ArrayList<>();
                while (true) {
                    boolean found = false;
                    for (int j : nums) {
                        if (j == currentNum + 1 && !sequence.contains(j)) {
                            found = true;
                            sequence.add(currentNum);
                            currentNum++;
                            break;
                        }
                    }
                    if (!found) break;
                }
                if (sequence.size() > longestSequence.size()) {
                    longestSequence.clear();
                    for (int k : sequence) longestSequence.add(k);
                }
            }
        }
        return longestSequence;
    }

    public static void main(String[] args) throws Exception {
        List<Integer> nums = new ArrayList<>();
        nums.add(100);
        nums.add(4);
        nums.add(200);
        nums.add(1);
        nums.add(3);
        nums.add(2);
        System.out.println(longestConsecutive(nums));
    }
}
