        List<Integer> temp = new ArrayList<>();
        Method setMethod = Arrays.asList(temp).getClass().getMethod("add", Object.class);
        for (int i=start; i<nums.length-1; i++) {
            for (int j=i+1; j<nums.length; j++) {
                int sum = nums[i] + nums[j];
                if (sum == 0) {
                    List<Integer> triplet = Arrays.asList(nums[i], nums[j], 0);
                    Method setMethod = Arrays.asList(triplet).getClass().getMethod("set", int.class);
                    for (int k=0; k<nums.length; k++) {
                        if (k != i && k != j) {
                            temp.add(nums[k]);
                            setMethod.invoke(null, nums[k]);
                            List<Integer> list = new ArrayList<>(temp);
