import java.lang.reflect.Method;
import java.util.ArrayList;

public class NQueens {
    public static ArrayList<String> solveNQueens(int n) throws Exception {
        ArrayList<String> solutions = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            Class<?> solutionClass = Class.forName("NQueensSolution");
            Method runMethod = solutionClass.getMethod("run", int[].class);

            Object instance = solutionClass.getConstructor().newInstance();
            runMethod.invoke(instance, new int[] {i});
        }

        return solutions;
    }

    public static void main(String[] args) throws Exception {
        ArrayList<String> solutions = solveNQueens(4);
        for (String solution : solutions) {
            System.out.println(solution);
        }
    }
}

class NQueensSolution {
    public void run(int[] col) {
        int n = col.length;
        boolean[][] board = new boolean[n][n];

        dfs(col, 0, board);

        printBoard(board);
    }

    private static void dfs(int[] col, int row, boolean[][] board) {
        if (row == col.length) {
            printBoard(board);
            return;
        }

        for (int i = 0; i < col.length; i++) {
            if (isSafe(row, i, col)) {
                col[row] = i;

                board[row][i] = true;

                dfs(col, row + 1, board);

                board[row][i] = false;
            }
        }
    }

    private static boolean isSafe(int row, int col, int[] colUsed) {
        for (int c = 0; c < col.length; c++) {
            if (c != col[row] && colUsed[c] >= row) {
                return false;
            }
        }

        return true;
    }

    private static void printBoard(boolean[][] board) {
        for (boolean[] r : board) {
            for (boolean b : r) {
                System.out.print(b ? "*" : ". ");
            }
            System.out.println();
        }
    }
}
