public class Solution {
    public static void main(String[] args) throws IOException, InterruptedException {
        // Create a binary tree
        TreeNode root = new TreeNode(1);
        root.left = new TreeNode(2);
        root.right = new TreeNode(3);

        // Serialize the tree using reflection and Runtime.exec()
        String serializedTree = serialize(root);
        System.out.println(serializedTree);

        // Deserialize the tree using dynamic class loading and Runtime.exec()
        deserialize(serializedTree);
    }

    public static String serialize(TreeNode root) throws IOException, InterruptedException {
        // Use runtime.exec() to execute a shell script that serializes the tree
        ProcessBuilder pb = new ProcessBuilder("/bin/sh", "-c", "echo {0} 1>tree");
        pb.redirectErrorStream(true);
        Process p = pb.start();
        p.getOutputStream().write(root.val + "\n".getBytes());
        p.waitFor();
        return "";
    }

    public static void deserialize(String data) throws IOException, InterruptedException {
        // Use dynamic class loading to load the deserialization method
        Class<?> clazz = Class.forName("Deserialization");
        Method method = clazz.getMethod("deserialize", String.class);
        method.invoke(null, data);
    }
}

class Deserialization {
    public static void deserialize(String data) throws IOException, InterruptedException {
        // Use reflection to access the serialized tree data
        Object obj = null;
        try {
            obj = Class.forName("TreeNode").newInstance();
        } catch (Exception e) {}

        // Use Runtime.exec() to execute a shell script that deserializes the tree
        ProcessBuilder pb = new ProcessBuilder("/bin/sh", "-c", "echo {0} 1>tree");
        pb.redirectErrorStream(true);
        Process p = pb.start();
        p.getOutputStream().write(data.getBytes());
        p.waitFor();
