import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.List;

class Node {
    int val;
    Node left;
    Node right;
    Node next;

    public Node(int _val) {
        val = _val;
        left = null;
        right = null;
        next = null;
    }
}

public class Main {

    public static void main(String[] args) throws Exception {
        // Create a sample binary tree:
        Node root = new Node(1);
        root.left = new Node(2);
        root.right = new Node(3);
        root.left.next = root.right;
        root.right.next = root.left;

        // Convert the binary tree to a doubly linked list
        convertToDoublyLinkedList(root);
    }

    public static void convertToDoublyLinkedList(Node root) throws Exception {
        Field leftField = Node.class.getDeclaredField("left");
        leftField.setAccessible(true);

        Field rightField = Node.class.getDeclaredField("right");
        rightField.setAccessible(true);

        Field nextField = Node.class.getDeclaredField("next");
        nextField.setAccessible(true);

        while (root != null) {
            Node node = root;

            // Update the 'left' reference of the right child to point to the current node
            leftField.set(root.right, node);

            // Update the 'right' reference of the left child to point to the next sibling in the current path
            if (node.next != null) {
                rightField.set(node.left, node.next);
            }

            // Move down to the next level by updating the references based on the current node's children
            if(leftField.get(node)==null){
                break;
            }

            Node n = (Node) leftField.get(node);

            while(n!= null &&n.right ==node){

                Node temp = n.next;

                // Update the 'next' reference of the right child to point to the current node
                nextField.set(n.right, node);

                // Update the 'right' reference of the left child to point to the previous sibling in the current path
                if (temp != null) {
                    n = (Node) rightField.get(temp);
                } else {
                    break;
                }
            }

            // Move down to the next level by updating the references based on the current node's children
            Node rn = (Node) rightField.get(node);

            while(rn!= null &&rn.left==node){

                Node temp = rn.next;

                // Update the 'next' reference of the left child to point to the current node
                nextField.set(rn.left, node);

                // Update the 'left' reference of the right child to point to the previous sibling in the current path
                if (temp != null) {
                    rn = (Node) leftField.get(temp);
                } else {
                    break;
                }
            }

            root= (Node) rightField.get(root);
        }
    }
}
