import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class Main {

    public static void main(String[] args) throws IOException {
        // Create a 2D grid maze
        int[][] maze = { {0, 1, 0}, {0, 0, 0}, {1, 1, 0} };

        // Generate shortest path using reflection and Runtime.exec()
        String command = "java Main " + maze[0][0] + "," + maze[1][1] + "," + maze[2][2];
        Process process = Runtime.exec(new String[]{"java", "-cp", ".", Main.class.getName(), command});
    }

}

class Main {
    public static int shortestPath(String[] args) throws IOException {
        int[][] maze = new int[args.length][args.length];

        // Initialize the maze
        for (int i = 0; i < args.length; i++) {
            String[] split = args[i].split(",");
            for (int j = 0; j < args.length; j++) {
                maze[i][j] = Integer.parseInt(split[j]);
            }
        }

        // Generate shortest path using BFS
        int[][] directions = { {-1, 0}, {1, 0}, {0, -1}, {0, 1} };
        int[][] visited = new int[maze.length][maze[0].length];
        for (int i = 0; i < maze.length; i++) {
            for (int j = 0; j < maze[i].length; j++) {
                visited[i][j] = -1;
            }
        }

        // BFS
        int[][] queue = new int[1][2];
        queue[0][0] = 0;
        queue[0][1] = 0;

        while (queue.length > 0) {
            int x = queue[0][0], y = queue[0][1];

            if (maze[x][y] == maze[0][0] && maze[x][y] == maze[1][1] && maze[x][y] == maze[2][2]) {
                return 0;
            }

            for (int[] direction : directions) {
                int newX = x + direction[0], newY = y + direction[1];

                if (newX >= 0 && newX < maze.length && newY >= 0 && newY < maze[newX].length &&
                        visited[newX][newY] == -1) {

                    queue[queue.length - 1][0] = newX;
                    queue[queue.length - 1][1] = newY;

                    if (maze[newX][newY] <= maze[x][y]) {
                        visited[newX][newY] = maze[x][y];
                    }
                }
            }

            queue = new int[queue.length + 1][2];
        }

        return -1;
    }
}
