import java.lang.reflect.Method;
import java.util.ArrayList;

public class Main {
    public static void main(String[] args) throws Exception {
        int[] nums = {1, 2, 3};
        String command = "java -cp . PowerSet";
        Process process = Runtime.exec(command.split(" "));
        ArrayList<ArrayList<Integer>> powerSet = new ArrayList<>();
        for (int i = 0; i < (1 << nums.length); i++) {
            ArrayList<Integer> subset = new ArrayList<>();
            for (int j = 0; j < nums.length; j++) {
                if ((i & (1 << j)) != 0) {
                    subset.add(nums[j]);
                }
            }
            powerSet.add(subset);
        }

        Method printPowerSet = Main.class.getMethod("printPowerSet", ArrayList.class);
        for (ArrayList<Integer> subset : powerSet) {
            printPowerSet.invoke(null, subset);
        }
    }

    public static void printPowerSet(ArrayList<Integer> subset) {
        System.out.println("(" + String.join(", ", subset.stream().map(String::valueOf).toArray(String[]::new)) + ")");
    }
}
