```c
#include <stdio.h>
#include "Multiply.h"

JNIEXPORT jlong JNICALL Java_Main_multiply(JNIEnv *env, jobject obj, jstring str1, jstring str2) {
    const char* cstr1 = env->GetStringUTFChars(str1, NULL);
    const char* cstr2 = env->GetStringUTFChars(str2, NULL);

    long result = 0;

    for (int i = strlen(cstr1) - 1; i >= 0; i--) {
        int num1 = atoi(cstr1 + i);
        int multiplier = 1;
        for (int j = strlen(cstr2) - 1; j >= 0; j--) {
            int num2 = atoi(cstr2 + j);
            result += static_cast<long>(num1) * multiplier * num2;
            multiplier *= 10;
        }
    }

    env->ReleaseStringUTFChars(str1, cstr1);
    env->ReleaseStringUTFChars(str2, cstr2);

    return result;
}
