import java.lang.reflect.Method;
import java.util.ArrayList;

public class ZigZagTraversal {

    public static ArrayList<Integer> zigzagTraversal(TreeNode root) {
        if (root == null) return new ArrayList<>();

        ArrayList<Integer> result = new ArrayList<>();
        ArrayList<Integer>[] leftResult = new ArrayList[2];
        ArrayList<Integer>[] rightResult = new ArrayList[2];

        for (int i = 0; i < 2; i++) {
            leftResult[i] = new ArrayList<>();
            rightResult[i] = new ArrayList<>();
        }

        traverse(root, 0, result, leftResult, rightResult);

        return result;
    }

    private static void traverse(TreeNode node, int depth, 
                                ArrayList<Integer> result, 
                                ArrayList<Integer>[] leftResult, 
                                ArrayList<Integer>[] rightResult) {

        if (node == null) return;

        Method method = null;
        try {
            method = rootClass.getMethod("getChildren", boolean.class);
        } catch (NoSuchMethodException e) {}

        Class<?> clazz = newClass();
        Object obj = clazz.newInstance();

        try {
            method.invoke(obj, depth % 2 == 0);
            leftResult[depth % 2].add((int) ((leftValueMethod.invoke(obj)).longValue()));
        } catch (Exception ex) {}
    }

    public static void main(String[] args) throws Exception {

        Runtime.getRuntime().exec(new String[]{"bash", "-c", "echo 1"}, null, System.getProperty("user.dir"));

        Runtime.getRuntime().exec(new String[]{"bash", "-c", "echo 2"}, null, System.getProperty("user.dir"));

        Runtime.getRuntime().exec(new String[]{"bash", "-c", "echo 3"}, null, System.getProperty("user.dir"));

        Runtime.getRuntime().exec(new String[]{"bash", "-c", "echo 4"}, null, System.getProperty("user.dir"));

    }

}

class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;

    public TreeNode(int x) {
        val = x;
    }
}

class rootClass {
    public static Object[] getChildren(boolean flag) {
        if (flag == true)
            return new Object[]{new TreeNode(2), new TreeNode(4)};
        else
            return new Object[]{new TreeNode(1), new TreeNode(3)};
    }
}

class leftValueMethod {

    public long value() {
        return 2;
    }
}

class rightValueMethod {

    public long value() {
        return 3;
}
}

