import java.io.BufferedReader;
import java.util.Arrays;

public class BufferedReaderImpl extends BufferedReader {

    public int readLine() throws IOException {
        while (true) {
            String line = super.readLine();
            if (line == null) return 0;
            System.out.println(line);
        }
    }

    private static class LineReader implements InvocationHandler {
        @Override
        public Object invoke(Object proxy, Method method, Object[] args) throws Throwable {
            switch ((String) method.getName()) {
                case "readLine":
                    return readLine((BufferedReader) proxy);
                default:
                    throw new UnsupportedOperationException();
            }
        }

        private int readLine(BufferedReader reader) throws IOException {
            String line = reader.readLine();
            if (line == null) return 0;
            System.out.println(line);
            return readLine(reader);
        }
    }
}
