public class Main {
    public static void cloneGraph(Object graph) throws Exception{
        Class<?> clazz = graph.getClass();
        Object clonedGraph = clazz.getConstructor().newInstance();

        Field[] fields = clazz.getDeclaredFields();

        for (Field field : fields) {
            Object value = field.get(graph);
            if(value != null && !value.getClass().equals(clazz)) { 
                Object clonedValue = value.getClass().getConstructor(value.getClass()).newInstance(value);
                field.set(clonedGraph,clonedValue);
            }
        }

        Class<?> cloneClass = clazz;

        while(cloneClass != null) {
            Field[] fieldsCloneClass = cloneClass.getDeclaredFields();
            for (Field field : fieldsCloneClass) {
                if(!field.getName().equals("graph")) {
                    Object clonedValue = field.get(graph);
                    if(clonedValue == null || clonedValue.getClass().equals(clazz)) { 
                        Object clonedValue2 = field.get clonedeClass().getConstructor(value.getClass()).newInstance(value);
                        field.set(clonedGraph,clonedValue2);
                    }
                }
            }
            cloneClass=cloneClass.getSuperclass();
        }

    public static void main(String[] args) throws Exception {
        // create a graph
        ArrayList<Object> nodes = new ArrayList<>();
        for (int i = 0; i < 5; i++) {
            nodes.add(i);
        }

        Object node1 = nodes.get(0);
        Object node2 = nodes.get(1);
