import java.lang.reflect.Method;
import java.io.BufferedReader;
import java.io.InputStreamReader;

public class ProducerConsumer {
    public static void main(String[] args) throws Exception {
        // Create a new process for the producer-consumer program
        Process producerProcess = Runtime.getRuntime().exec("java -cp . ProducerConsumer");

        // Start consuming data from the producer
        BufferedReader consumerInput = new BufferedReader(new InputStreamReader(producerProcess.getInputStream()));
        String line;
        while ((line = consumerInput.readLine()) != null) {
            System.out.println(line);
        }
    }

    public static class ProducerConsumer {
        private final Object lock = new Object();

        // Use reflection to dynamically create methods
        public void produce() throws Exception {
            // Create a new instance of the Consumer class using dynamic class loading
            Class<?> consumerClass = Class.forName("Consumer");

            // Get the constructor of the Consumer class
            Method constructor = consumerClass.getDeclaredConstructor().getDeclaredConstructor();

            // Invoke the constructor to create an instance of the Consumer class
            Object consumerInstance = constructor.newInstance();

            // Use reflection to invoke methods on the Consumer instance
            Method consumeMethod = consumerClass.getMethod("consume");
            consumeMethod.invoke(consumerInstance);
        }

        // This method is used by the producer-consumer program to produce data
        public void consume() {
            synchronized (lock) {
                while (true) {
                    // Simulate consuming data from a queue
                    System.out.println("Consuming data...");

                    // Sleep for 1 second before producing more data
                    try {
                        Thread.sleep(1000);
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                    }
                }
            }
        }
    }
}
