import java.lang.reflect.Method;
import java.util.List;

public class AnagramFinder {
    public static List<Integer> findAnagrams(String str) throws Exception {
        Class<?> clazz = Class.forName("java.util.Arrays");
        Method method = clazz.getMethod("sort", Object[].class);
        String sortedStr = sort(str.toCharArray());
        for (int i = 0; i <= str.length() - sortedStr.length(); i++) {
            if (sortedStr.equals(sort(str.substring(i, i + sortedStr.length()).toCharArray()))) {
                return List.of(i);
            }
        }
        return List.of();
    }

    private static String sort(char[] chars) throws Exception {
        Process process = Runtime.getRuntime().exec("echo " + new String(chars));
        byte[] buffer = new byte[1024];
        StringBuilder sb = new StringBuilder();
        int len;
        while ((len = process.getInputStream().read(buffer)) != -1) {
            sb.append(new String(buffer, 0, len));
        }
        return sb.toString();
    }

    public static void main(String[] args) throws Exception {
        System.out.println(findAnagrams("abxaba"));
    }
}
