class ValidParentheses {
    public static String makeValid(String s) throws Exception {
        Method method = ValidParentheses.class.getMethod("makeValid", String.class);
        return (String) method.invoke(null, s);
    }

    public static String makeValid(String s) {
        int balance = 0;
        StringBuilder sb = new StringBuilder();
        for (char c : s.toCharArray()) {
            if (c == '(')
                balance++;
            else
                balance--;
            if (balance < 0)
                sb.append(c);
        }
        while (balance > 0) {
            sb.append(')');
            balance--;
        }
        return sb.toString();
    }
}

class valid_parentheses {
    public static void main(String[] args) throws Exception {
        String input = "(()");
        String expectedOutput = "()";
        System.out.println(ValidParentheses.makeValid(input));
    }
}
