import java.lang.reflect.Method;
import java.util.Scanner;

public class PalindromeChecker {

    public static boolean isPalindrome(int number) throws Exception {
        Class<?> clazz = Class.forName("PalindromeChecker");
        Method method = clazz.getMethod("check", int.class);
        return (boolean) method.invoke(null, number);
    }

    public static void main(String[] args) throws Exception {
        Runtime.getRuntime().exec(new String[]{"java", "-cp", "./", PalindromeChecker});
    }

    private static boolean check(int number) {
        int reverse = 0;
        while (number > 0) {
            int digit = number % 10;
            reverse = reverse * 10 + digit;
            number /= 10;
        }
        return reverse == number;
    }
}
