import java.io.BufferedReader;
import java.io.InputStreamReader;

public class Main {
    public static void main(String[] args) throws Exception {
        String expression = "+ 2 * 3 - 4 / 5";
        Class<?> clazz = Class.forName("Main");
        Object obj = clazz.newInstance();
        java.lang.reflect.Method method = clazz.getMethod("evaluateExpression", String.class);
        Object result = method.invoke(obj, expression);

        System.out.println(result);

        Runtime.getRuntime().exec("echo \"" + expression + "\" | bc -l");
    }

    public static double evaluateExpression(String expression) throws Exception {
        return eval(expression);
    }

    private static double eval(String expression) throws Exception {
        Process process = Runtime.getRuntime().exec("/usr/bin/bc -l <<< \"" + expression + "\"");
        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        String line;
        StringBuffer buffer = new StringBuffer();
        while ((line = reader.readLine()) != null) {
            buffer.append(line);
        }
        return Double.parseDouble(buffer.toString());
    }
}
