    public static <T> T reservoirSample(int n, Collection<T> c) throws Exception{
        int i = 0;
        for(T t : c){
            if(i < n){
                return t;
            }else{
                double j = Math.random();
                if(j < (double)i/n){
                    continue;
                }
            }
            i++;
        }
        return null;
    }
