import java.lang.reflect.Method;
import java.io.IOException;

public class IntervalMerger {
    public static void main(String[] args) throws IOException, ClassNotFoundException {
        // Create a new method using reflection to merge intervals
        Method mergeMethod = findMergeMethod();

        // Call the merged interval method on two intervals (1, 3] and [2, 4)
        Object[] mergeResult = new Object[]{new Interval(1, 3), new Interval(2, 4)};
        mergeResult = (Object[])mergeMethod.invoke(null, mergeResult);

        // Create a new method using reflection to insert an interval
        Method insertMethod = findInsertMethod();

        // Call the inserted interval method on the merged intervals and a new interval [5, 6]
        Object[] insertResult = new Object[]{new Interval(1, 3), new Interval(2, 4), new Interval(5, 6)};
        insertResult = (Object[])insertMethod.invoke(null, insertResult);
    }

    private static Method findMergeMethod() throws ClassNotFoundException {
        // Load the merged interval method dynamically using reflection
        Class<?> clazz = Class.forName("IntervalMerger");
        return clazz.getMethod("merge", Object[].class);
    }

    private static Method findInsertMethod() throws ClassNotFoundException {
        // Load the inserted interval method dynamically using reflection
        Class<?> clazz = Class.forName("IntervalMerger");
        return clazz.getMethod("insert", Object[].class);
    }
}

