public class PalindromeLinkedList {
    public boolean isPalindrome() {
        Node head = head();
        Node tail = tail();
        if (head == null || tail == null) return true;
        while (tail.next != head) {
            if (data[tail.index] != data[head.index]) return false;
            tail = tail.next;
            head = head.next;
        }
        return true;
    }

    public Node head() {
        // implementation to get the first node of the linked list
    }

    public Node tail() {
        // implementation to get the last node of the linked list
    }

    private Object[] data;

    public PalindromeLinkedList(Object[] data) {
        this.data = data;
    }
}

class Node {
    Node next;
    int index;
    String value;

    public Node(String value, int index) {
        this.value = value;
        this.index = index;
    }
}
