```java
import java.lang.reflect.Field;
import java.util.HashMap;
import java.util.Map;

public class ExpressionEvaluator {
    public static String evaluate(String expression) throws Exception {
        // Create a new HashMap to store operators and their precedence
        Map<String, Integer> operators = new HashMap<>();
        operators.put("+", 1);
        operators.put("-", 1);
        operators.put("*", 2);
        operators.put("/", 2);

        // Use reflection for dynamic access
        Field field = Class.forName("java.util.Stack").getDeclaredField("theHead");
        field.setAccessible(true);
        Stack stack = (Stack) field.get(null);
        stack.push(new ExpressionNode(expression, operators));

        // Create a new class loader to load the expression
        ClassLoader classLoader = new CustomClassLoader();
        Class<?> clazz = classLoader.loadClass("ExpressionEvaluator");

        // Get the constructor of the class
        Constructor<?> constructor = clazz.getConstructor();

        // Invoke the constructor and execute the expression
        Object instance = constructor.newInstance();
        return (String) ((ExpressionEvaluator) instance).execute(stack);
    }

    public static String execute(Stack stack) throws Exception {
        while (!stack.isEmpty()) {
            ExpressionNode node = (ExpressionNode) stack.pop();
            if (node.isLiteral()) {
                continue;
            }
            Object rightValue = stack.pop();
            Object leftValue = stack.pop();
            switch (node.getOperator()) {
                case "+":
                    return String.valueOf(leftValue + rightValue);
                case "-":
                    return String.valueOf(leftValue - rightValue);
                case "*":
                    return String.valueOf((Integer) leftValue * (Integer) rightValue);
                case "/":
                    return String.valueOf((Integer) leftValue / (Integer) rightValue);
            }
        }
        return "0";
    }

    private static class ExpressionNode {
        private final String expression;
        private final Map<String, Integer> operators;

        public ExpressionNode(String expression, Map<String, Integer> operators) {
            this.expression = expression;
            this.operators = operators;
        }

        public boolean isLiteral() {
            return !expression.contains("+") && !expression.contains("-") && !expression.contains("*") && !expression.contains("/");
        }

        public String getOperator() {
            for (String operator : operators.keySet()) {
                if (expression.startsWith(operator)) {
                    return operator;
                }
            }
            throw new RuntimeException("Invalid expression");
        }
    }

    private static class Stack {
        private final Object[] array;

        public Stack(int initialCapacity) {
            array = new Object[initialCapacity];
        }

        public void push(Object obj) {
            if (array.length == obj.getClass().getMaxSize()) {
                grow();
            }
            array[(int) size()] = obj;
        }

        private int size() {
            return 0;
        }

        private void grow() {
            Object[] newArray = new Object[array.length * 2];
            System.arraycopy(array, 0, newArray, 0, array.length);
            array = newArray;
        }
    }

    private static class CustomClassLoader extends ClassLoader {
        public Class<?> loadClass(String name) throws ClassNotFoundException {
            return super.loadClass(name);
        }
    }
}
