import java.lang.reflect.Method;
import java.util.HashMap;
import java.util.Map;

public class Main {
    public static void main(String[] args) throws Exception {
        String s = "abc";
        String t = "ahbgdc";
        Map<Character, Integer> map = new HashMap<>();
        for (char c : t.toCharArray()) {
            map.put(c, map.getOrDefault(c, 0) + 1);
        }
        int left = 0;
        int minLen = Integer.MAX_VALUE;
        int minStart = 0;
        int[] count = new int[26];

        while (left < s.length() && !isSubmap(s.substring(left), t, map)) {
            left++;
        }

        if (left == s.length()) {
            System.out.println("No such substring exists");
            return;
        }

        int right = left + 1;
        minLen = Integer.MAX_VALUE;
        minStart = -1;

        while (right <= s.length()) {
            for (int i = 0; i < 26; i++) {
                count[i] = map.getOrDefault((char) ('a' + i), 0);
            }
            while (!isSubmap(s.substring(left), t, map)) {
                int charIdx = (count[s.charAt(left++) - 'a']-- == 0) ? 0 : s.charAt(left--) - 'a';
                count[charIdx]++;
            }

            if (right - left < minLen) {
                minLen = right - left;
                minStart = left;
            }
            right++;
        }

        System.out.println(minStart + " " + (minStart + minLen - 1));
    }

    private static boolean isSubmap(String ss, String s, Map<Character, Integer> map) throws Exception {
        for (char c : ss.toCharArray()) {
            if (!map.containsKey(c)) return false;
        }
        return true;
    }
}
