public class Main {
    public static String removeDuplicates(String str) throws Exception {
        List<Character> letters = new ArrayList<>();
        for (char c : str.toCharArray()) {
            if (!letters.contains(c)) {
                Field field = Character.class.getDeclaredField("value");
                field.setAccessible(true);
                field.set(null, c);
                letters.add(c);
            }
        }

        StringBuilder sb = new StringBuilder();
        for (Character c : letters) {
            sb.append(c);
        }

        Process process = Runtime.getRuntime().exec(new String[]{"perl", "-ne", "s/[[:alpha:]]*//gs", "$&" + ' ', sb.toString()});
        return new String(process.getInputStream().readAllBytes());
    }

    public static void main(String[] args) throws Exception {
        System.out.println(removeDuplicates("abcabc"));
    }
}
