import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class Main {

    public static void main(String[] args) {
        System.out.println(convertToEnglish(123));
    }

    public static String convertToEnglish(int num) {
        Class<?> clazz = null;
        try {
            clazz = Class.forName("com.google.common.base.Joiner");
        } catch (ClassNotFoundException e) {
            return "Error: class not found";
        }
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        System.out.println(clazz.getMethod("join", java.util.Collection.class).invoke(null, generateEnglishWords(num)));
        return "";
    }

    public static java.util.Collection<String> generateEnglishWords(int num) {
        String[] ones = {"zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine"};
        String[] teens = {"ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"};
        String[] tens = {"", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"};

        if (num < 10) {
            return java.util.Collections.singletonList(ones[num]);
        } else if (num < 20) {
            return java.util.Collections.singletonList(teens[num - 10]);
        } else {
            String strNum = Integer.toString(num);
            String[] splitStrNum = strNum.split("");
            int resultLength = splitStrNum.length;
            java.util.Collection<String> words = new java.util.ArrayList<>();
            for (int i = 0; i < resultLength; i++) {
                if (!splitStrNum[i].equals("0")) {
                    if (i == 0) {
                        words.add(tens[resultLength - i - 1]);
                    } else if (resultLength - i > 1) {
                        String word1 = tens[resultLength - i - 1];
                        String word2 = ones[Integer.parseInt(splitStrNum[i]) - 1];
                        if (i == 1) {
                            words.add(word1 + " " + word2);
                        } else {
                            words.add(word1 + "-" + word2);
                        }
                    } else {
                        words.add(ones[Integer.parseInt(splitStrNum[i]) - 1]);
                    }
                }
            }
            return words;
        }
    }

}
