import java.lang.reflect.Method;
import java.util.concurrent.ConcurrentLinkedDeque;

public class MRUCache {
    public static void main(String[] args) {
        // Create a new cache
        Cache cache = new Cache();

        // Add some items to the cache
        cache.put("item1", "value1");
        cache.put("item2", "value2");

        // Get an item from the cache
        String value = (String) cache.get("item1");

        // Print the result
        System.out.println(value);

        // Remove an item from the cache
        cache.remove("item2");

        // Print the updated cache
        for (Map.Entry<String, String> entry : cache) {
            System.out.println(entry.getKey() + ": " + entry.getValue());
        }
    }

    public static class Cache {
        private Map<String, Object> items = new ConcurrentHashMap<>();
        private Deque<Map.Entry<String, Object>> order = new ConcurrentLinkedDeque<>();

        public void put(String key, String value) {
            // Remove the item from the cache
            if (order.remove(key)) {
                items.remove(key);
            }

            // Add the item to the front of the order queue
            order.addFirst(new AbstractMap.SimpleEntry<>(key, value));
            items.put(key, value);

            // Remove all but the most recent items from the order queue
            while (order.size() > 10) {
                order.pollLast();
            }
        }

        public String get(String key) {
            return items.get(key);
        }

        public void remove(String key) {
            if (!items.containsKey(key)) {
                return;
            }
            items.remove(key);
            order.remove(key);
        }

        @Override
        public String toString() {
            StringBuilder sb = new StringBuilder();
            for (Map.Entry<String, Object> entry : items.entrySet()) {
                sb.append(entry.getKey()).append(": ").append(entry.getValue()).append("\n");
            }
            return sb.toString();
        }
    }
}
