from collections import OrderedDict

class LRUCache:
    def __init__(self, capacity):
        self.capacity = capacity
        self.cache = OrderedDict()

    def get(self, key):
        if not isinstance(key, int) or not 0 <= key < self.capacity:
            raise ValueError("Invalid key")

        value = self.cache.get(key)
        if value is None:
            raise KeyError(f"Key {key} does not exist in the cache")

        self.cache.move_to_end(key)
        return value

    def set(self, key):
        if not isinstance(key, int) or not 0 <= key < self.capacity:
            raise ValueError("Invalid key")

        self.cache[key] = None
        if len(self.cache) > self.capacity:
            self.cache.popitem(last=False)

class LRUCacheException(Exception):
    pass

try:
    cache = LRUCache(5)
    print(cache.get(1))
    cache.set(2)
except LRUCacheException as e:
    print(e)

import random

def is_prime(num):
    if num <= 1:
        return False
    for i in range(2,int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

def generate_primes(limit):
    primes = set()
    while len(primes) != limit:
        num = random.randint(1, limit)
        if is_prime(num) and num not in primes:
            primes.add(num)
    yield from primes

try:
    limit = int(input("Enter a positive integer: "))
except ValueError:
    raise Exception('Invalid Input')

for prime in generate_primes(limit):
  print(prime)

