from functools import wraps
import hashlib

def memoize(func):
    cache = {}

    @wraps(func)
    def wrapper(*args):
        args_tuple = str(args).encode('utf-8')
        args_hash = hashlib.sha256(args_tuple).hexdigest()

        if args_hash in cache:
            return cache[args_hash]

        result = func(*args)
        cache[args_hash] = result
        return result

    return wrapper

# Example usage:

@memoize
def fibonacci(n):
    if n < 2:
        return n
    return fibonacci(n-1) + fibonacci(n-2)

print(fibonacci(10))  # This will take longer on the first call, but subsequent calls with the same argument will be much faster.
