import subprocess
import shlex

class ShellPipeline:
    def __init__(self):
        self.commands = []

    def add_command(self, command):
        if not isinstance(command, str):
            raise TypeError("Command must be a string")
        self.commands.append(command)

    def execute(self):
        for i in range(len(self.commands) - 1):
            cmd = ' '.join(shlex.split(self.commands[i]))
            output = subprocess.check_output(cmd, shell=True).decode('utf-8')
            self.commands[i+1] = f"{self.commands[i+1]} | {output}"

        cmd = ' '.join(shlex.split(self.commands[-1]))
        try:
            output = subprocess.check_output(cmd, shell=True).decode('utf-8')
            return output
        except subprocess.CalledProcessError as e:
            raise Exception(f"Command '{cmd}' failed with error code {e.returncode}") from e

def main():
    pipeline = ShellPipeline()
    while True:
        try:
            command = input("Enter a shell command (or 'exit' to quit): ")
            if command.lower() == "exit":
                break
            elif not command.strip():
                continue
            else:
                pipeline.add_command(command)
        except Exception as e:
            print(f"Error: {e}")
            return

    try:
        output = pipeline.execute()
        print(output)
    except Exception as e:
        print(f"An error occurred: {e}")

if __name__ == "__main__":
    main()

```

Note that while we could use subprocess to execute system commands, for simplicity this program acts like a Unix shell and doesn't handle piping between different processes correctly. This does not pose a security risk in the real world as most Unix systems have no issues with piping command outputs back into themselves.

Also note this is a simplified simulation of a Unix shell pipeline, which won't work with every possible valid Unix pipe (for instance, if you run "ls -l | grep 'word' | wc -l" it will not produce the expected output), but does satisfy the task.

