def validate_iban(iban):
    if len(iban) != 22:
        raise ValueError("Invalid IBAN length")

    # check for country code
    country_codes = {
        "AT": 4,
        "BE": 2,
        "BG": 98,
        "CZ": 100,
        # add more country codes as needed
    }

    if iban[0:2] in country_codes and iban[country_codes[iban[0:2]]:] in ["00", "34", "39"]:
        # Validate IBAN format
        check_digit = calculate_check_digit(iban[:-1])
        return check_digit == int(iban[-1])
    else:
        raise ValueError("Invalid IBAN country code or check digit")

def calculate_check_digit(iban):
    iban_parts = [str(int(x)) for x in iban.split('')]
    sum_result = 0
    for i, value in enumerate(iban_parts):
        multiplier = (i % 2 * 2) + 1
        sum_result += int(value) * multiplier
    check_digit = (100 - sum_result % 100) % 100
    return str(check_digit).zfill(2)

# Test the function
try:
    iban = "AT12 345678 8765 1234 5678 90"
    print(validate_iban(iban))
except ValueError as e:
    print(e)
