import re

def generate_palindromes(s):
    s = re.sub(r'[^a-zA-Z0-9]', '', s)

    if not s:
        return []

    palindromes = set()
    stack = [(s, 0, len(s) - 1)]

    while stack:
        current_str, start, end = stack.pop()

        for i in range(start, end + 1):
            substring = current_str[start:i+1]

            if substring == substring[::-1]:
                palindromes.add(substring)

                # Generate all possible substrings that are not a palindrome
                for j in range(i + 2, end + 2):
                    next_substring = current_str[i:j]

                    if next_substring != next_substring[::-1] and len(next_substring) > 0:
                        stack.append((current_str[:i] + next_substring, 0, i - 1))
                        stack.append((current_str[i:j], j, end))

    return sorted(list(palindromes))


