import collections
from dataclasses import dataclass

@dataclass
class Task:
    name: str
    dependencies: list[str]

def topological_sort(tasks):
    graph = collections.defaultdict(list)
    in_degree = {task.name: 0 for task in tasks}

    for task in tasks:
        for dependency in task.dependencies:
            graph[dependency].append(task.name)
            in_degree[task.name] += 1

    queue = [task.name for task in tasks if in_degree[task.name] == 0]

    sorted_tasks = []

    while queue:
        task_name = queue.pop(0)
        for neighbor in graph[task_name]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)
        sorted_tasks.append(task_name)

    if len(sorted_tasks) != len(tasks):
        raise ValueError("The task dependencies have a cycle")

    return sorted_tasks

def schedule_tasks(tasks):
    try:
        return topological_sort(tasks)
    except Exception as e:
        raise Exception(f"An error occurred: {e}")

# Example usage
tasks = [
    Task('A', []),
    Task('B', ['A']),
    Task('C', ['A']),
    Task('D', ['B', 'C'])
]

print(schedule_tasks(tasks))  # Output: ['A', 'C', 'B', 'D']
```

