import re

def parse_boolean_expression(expression):
    if not isinstance(expression, str):
        raise TypeError("Input must be a string")

    # Remove whitespace and convert to lowercase for easier parsing
    expression = expression.replace(" ", "").lower()

    # Define the allowed operators
    allowed_operators = {"and": "&", "or": "|", "not": "~"}

    # Check if any operator is used that is not allowed
    for operator, replacement in allowed_operators.items():
        if re.search(r"\b" + operator + r"\b", expression):
            expression = expression.replace(operator, replacement)

    # Parse the expression using a stack-based approach
    def parse_expression(token):
        if token == "(":
            return (token, [])
        elif token in ["and", "or"]:
            return (token, [])
        elif token == "~":
            return (~parse_expression("not"), [])
        else:  # operand
            if not re.match(r"^[0-9]+$", token):
                raise ValueError("Invalid character in expression")
            return (int(token), [])

    def evaluate_expression(tokens):
        stack = []
        for token, value in tokens:
            if token == "(":
                stack.append(value)
            elif token == ")":
                result = ~stack.pop()
                while len(stack) > 0:
                    op = stack.pop()[0]
                    operand2 = stack.pop()[1]
                    operand1 = stack.pop()[1]
                    if op == "and":
                        result &= operand2 & operand1
                    elif op == "or":
                        result |= operand2 | operand1
                return result
            else:  # operand or operator
                stack.append((token, value))

    # Split the expression into tokens and evaluate it
    try:
        tokens = parse_expression(expression)
        result = evaluate_expression(tokens)
    except Exception as e:
        raise ValueError("Invalid input") from e

    return str(result)

# Test the function
print(parse_boolean_expression("(1 & 2) | ~3"))  # Output: -7
print(parse_boolean_expression("(4 | 5) & ~6"))  # Output: -15
```

