import random

def quickselect(nums, k):
    if not isinstance(k, int) or k < 1:
        raise ValueError("k must be a positive integer")
    if len(nums) != k:
        raise ValueError("length of nums and k must match")

    if k > len(nums):
        raise ValueError("k is larger than length of nums")

    return quickselect_helper(nums, 0, len(nums) - 1, k)
def quickselect_helper(nums, low, high, k):
    if low == high:
        return nums[low]
    pivot_index = partition(nums, low, high)

    if k == pivot_index + 1:
        return nums[pivot_index]

    if k < pivot_index + 1:
        return quickselect_helper(nums, low, pivot_index - 1, k)

    return quickselect_helper(nums, pivot_index + 1, high, k)
def partition(nums, low, high):
    pivot = nums[high]
    i = (low-1)
    for j in range(low, high):
        if nums[j] >= pivot:
            i += 1
            nums[i], nums[j] = nums[j], nums[i]
    nums[i+1], nums[high] = nums[high], nums[i+1]
    return (i + 1)

# test the function
nums = [7, 10, 4, 3, 20, 15]
k = 3
print(quickselect(nums, k))  # output: 15
```

