class Node:
    def __init__(self, id):
        self.id = id

class Edge:
    def __init__(self, from_node_id, to_node_id):
        self.from_node_id = from_node_id
        self.to_node_id = to_node_id

class DAG:
    def __init__(self):
        self.nodes = {}
        self.edges = {}

    def add_node(self, id):
        if not isinstance(id, int) or id <= 0:
            raise ValueError("Node ID must be a positive integer")
        self.nodes[id] = Node(id)

    def remove_node(self, node_id):
        if node_id in self.nodes and self.has_edge(node_id):
            raise ValueError(f"Cannot remove node with edges: {self.get_edges(node_id)}")
        del self.nodes[node_id]

    def add_edge(self, from_node_id, to_node_id):
        if not isinstance(from_node_id, int) or not isinstance(to_node_id, int) or from_node_id <= 0 or to_node_id <= 0:
            raise ValueError("Node IDs must be positive integers")
        if from_node_id in self.nodes and to_node_id in self.nodes:
            Edge(from_node_id, to_node_id)
            self.edges[(from_node_id, to_node_id)] = None

    def remove_edge(self, node_id):
        if not isinstance(node_id, int) or node_id <= 0:
            raise ValueError("Node ID must be a positive integer")
        for edge_id in list(self.edges.keys()):
            if self.edges[edge_id] is None and edge_id[0] == node_id and edge_id[1] == node_id:
                del self.edges[edge_id]
            elif self.edges[edge_id] is not None and edge_id[0] == node_id or edge_id[1] == node_id:
                break

    def has_edge(self, node_id):
        for edge in list(self.edges.keys()):
            if edge[0] == node_id or edge[1] == node_id:
                return True
        return False

    def get_edges(self, node_id):
        edges = []
        for edge in self.edges.keys():
            if edge[0] == node_id or edge[1] == node_id:
                edges.append(edge)
        return edges

    def to_dict(self):
        dag_dict = {'nodes': [], 'edges': []}
        for node_id, node in self.nodes.items():
            dag_dict['nodes'].append({'id': node_id})
        for edge from_node_id, to_node_id in self.edges.keys():
            if (from_node_id, to_node_id) not in list(self.edges.keys())[::-1]:
                dag_dict['edges'].append((to_node_id, from_node_id))
        return dag_dict

# Testing
dag = DAG()
dag.add_node(1)
dag.add_node(2)
dag.add_edge(1, 2)

print(dag.to_dict())

dag.remove_node(1)

print(dag.to_dict())
