def detect_language(input_string):
    if not isinstance(input_string, str) or len(input_string.strip()) == 0:
        raise ValueError("Input must be a non-empty string.")

    language_frequencies = {
        'english': {'the': 1.23, 'of': 2.34, 'and': 3.45},
        'spanish': {'de': 1.23, 'la': 2.34, 'y': 3.45},
        'french': {'le': 1.23, 'la': 2.34, 'et': 3.45}
    }

    language = None
    max_frequency = 0

    for lang, freq_dict in language_frequencies.items():
        frequency_sum = sum(freq_dict.values())
        proportion = (sum(val for val in input_string.lower().split() if val in freq_dict) / len(input_string.lower().split())) * frequency_sum
        if proportion > max_frequency:
            max_frequency = proportion
            language = lang

    return language

try:
    print(detect_language("Hello world!"))
except ValueError as e:
    print(e)
