import emoji

def count_emoji_frequency(text):
    # Validate input type
    if not isinstance(text, str):
        raise TypeError("Input must be a string.")

    # Initialize dictionary to store frequency of each emoji
    emoji_freq = {}

    # Iterate over each character in the text
    for char in text:
        try:
            # Check if character is an emoji
            if char in emoji.emoji_data:
                # Increment count of emoji in dictionary
                emoji_freq[char] = emoji_freq.get(char, 0) + 1
        except Exception as e:
            # Handle any exceptions while processing emojis
            raise Exception(f"Error processing emoji: {str(e)}")

    return emoji_freq

