import sys
import os
from itertools import zip_longest

def merge_sorted_log_files(file_paths):
    if not file_paths:
        raise ValueError("No log files provided")

    try:
        with open(os.path.join(sys.argv[1]), 'w') as merged_file:
            for line in zip_longest(*file_paths, fillvalue=''):
                for file_line in line:
                    merged_file.write(file_line)
    except Exception as e:
        print(f"An error occurred: {e}")

if __name__ == "__main__":
    if len(sys.argv) != 2:
        raise ValueError("Please provide the output log file path")

    try:
        with open(sys.argv[1], 'w') as output_log_file:
            for file_path in sys.argv[1:]:
                with open(file_path, 'r') as file:
                    lines = file.readlines()
                    for line in lines:
                        output_log_file.write(line)
    except Exception as e:
        print(f"An error occurred: {e}")
```
