import random

class SudokuBoard:
    def __init__(self, board):
        self.board = board

    def validate_board(self):
        if len(self.board) != 9 or any(len(row) != 9 for row in self.board):
            raise ValueError("Invalid board size")
        for i in range(9):
            row = set(str(x) for x in self.board[i])
            if len(row) != 9:
                raise ValueError("Duplicate values in a row or column")
            col = set([self.board[j][i] for j in range(9)])
            if len(col) != 9:
                raise ValueError("Duplicate values in a row or column")

    def solve(self):
        for i in range(9):
            for j in range(9):
                if self.board[i][j] == 0:
                    possible_values = set(range(1, 10))
                    for x in range(9):
                        if self.board[x][j] != 0 and self.board[x][j] not in possible_values:
                            possible_values.remove(self.board[x][j])
                    for y in range(9):
                        if self.board[i][y] != 0 and self.board[i][y] not in possible_values:
                            possible_values.remove(self.board[i][y])
                    for x in range(3 * (i // 3), 3 * (i // 3) + 3):
                        for y in range(3 * (j // 3), 3 * (j // 3) + 3):
                            if self.board[x][y] != 0 and self.board[x][y] not in possible_values:
                                possible_values.remove(self.board[x][y])
                    num = random.choice(list(possible_values))
                    while num == 0 or num in [self.board[x][j] for x in range(9)] or num in [self.board[i][y] for y in range(9)] or num in [self.board[x][y] for x in range(3 * (i // 3), 3 * (i // 3) + 3) for y in range(3 * (j // 3), 3 * (j // 3) + 3)]:
                        possible_values.remove(num)
                    self.board[i][j] = num

    def print_board(self):
        for i in range(9):
            if i % 3 == 0 and i != 0:
                print("- - - - - - - - - - - -")
            for j in range(9):
                if j % 3 == 0 and j != 0:
                    print("| ", end="")
                if j == 8:
                    print(self.board[i][j])
                else:
                    print(str(self.board[i][j]) + " ", end="")

def main():
    board = [[5, 3, 0, 0, 7, 0, 0, 0, 0],
             [6, 0, 0, 1, 9, 5, 0, 0, 0],
             [0, 9, 8, 0, 0, 0, 0, 6, 0],
             [8, 0, 0, 0, 6, 0, 0, 0, 3],
             [4, 0, 0, 8, 0, 3, 0, 0, 1],
             [7, 0, 0, 0, 2, 0, 0, 0, 6],
             [0, 6, 0, 0, 0, 0, 2, 8, 0],
             [0, 0, 0, 4, 1, 9, 0, 0, 5],
             [0, 0, 0, 0, 8, 0, 0, 7, 9]]

    board_sudoku = SudokuBoard(board)
    try:
        board_sudoku.validate_board()
        board_sudoku.solve()
        board_sudoku.print_board()
    except ValueError as e:
        print(f"Error: {e}")

if __name__ == "__main__":
    main()
```

This code defines a class `SudokuBoard` to represent the Sudoku board and solve it. The `validate_board` method checks if the board is valid, the `solve` method solves the Sudoku puzzle using a backtracking algorithm with randomization for possible values, and the `print_board` method prints the solved board. The code also includes input validation and error handling to ensure that the board is valid before attempting to solve it.

