import secrets
import string

def generate_password(complexity):
    if complexity < 8:
        raise ValueError("Password complexity should be at least 8")

    chars = string.ascii_letters + string.digits + string.punctuation

    # Determine the length of the password based on complexity
    length = complexity // 5 + 1

    # Ensure the length is at least 12 for maximum security
    if length < 12:
        length = 12

    password = ''.join(secrets.choice(chars) for _ in range(length))

    return password

def main():
