import re
from decimal import Decimal, InvalidOperation

def parse_and_evaluate_expression(expression: str) -> float:
    if not isinstance(expression, str):
        raise TypeError("Input must be a string")

    # Remove any whitespace from the expression
    expression = re.sub(r'\s', '', expression)

    try:
        # Replace '^' with '**' to make exponentiation work correctly in Python 3
        expression = expression.replace('^', '**')

        # Try to evaluate the expression using the eval() function, but only if it's safe to do so
        def is_safe_eval(expression: str) -> bool:
            for char in expression:
                if not (char.isdigit() or char in '+-*/(). '):
                    return False
            return True

        if is_safe_eval(expression):
            # Convert the input string into a Python expression using the ast module
            import ast

            tree = ast.parse(expression, mode='eval')

            # Create an instance of the ast.Module class to evaluate the expression
            class SafeEvaluator(ast.NodeTransformer):
                def visit_Name(self, node):
                    return str(node.id)

                def generic(self, node):
                    return str(node)

            evaluator = SafeEvaluator()
            result = eval(evaluator.visit(node), {'__builtins__': None}, {})
            return float(result)
        else:
            raise ValueError("Invalid characters in the expression")
    except InvalidOperation as e:
        # Catch any invalid operations that occur during evaluation
        raise ValueError(f"Invalid operation: {e}")
    except Exception as e:
        # Catch any other exceptions that occur during evaluation
        raise ValueError(f"An error occurred while evaluating the expression: {e}")

# Example usage:
expression = input("Enter a mathematical expression (in Python 3 syntax): ")
result = parse_and_evaluate_expression(expression)
print(result)
