import jwt
from datetime import datetime, timedelta

def create_jwt(payload, secret_key):
    try:
        # Create JWT token with payload and secret key
        token = jwt.encode(payload, secret_key, algorithm="HS256")
        return token
    except jwt.ExpiredSignatureError:
        raise Exception("JWT Token has expired")
    except jwt.InvalidTokenError as e:
        raise Exception(f"Invalid JWT Token: {str(e)}")

def validate_jwt(token, secret_key):
    try:
        # Validate JWT token with payload and secret key
        decoded_token = jwt.decode(token, secret_key, algorithms=["HS256"])
        return decoded_token
    except jwt.InvalidTokenError as e:
        raise Exception(f"Invalid JWT Token: {str(e)}")

def main():
    # Example usage
    payload = {
        "user_id": 1,
        "exp": datetime.utcnow() + timedelta(minutes=30)
    }
    secret_key = "my_secret_key"

    token = create_jwt(payload, secret_key)
    print("JWT Token:", token)

    try:
        decoded_token = validate_jwt(token, secret_key)
        print("Decoded JWT Payload:", decoded_token)
    except Exception as e:
        print(f"Error: {str(e)}")

if __name__ == "__main__":
    main()
```

