import random

def roll_dice(dice_names):
    if not isinstance(dice_names, list) or len(dice_names) == 0:
        raise ValueError("Input must be a non-empty list of strings.")

    rolls = {}
    for name in dice_names:
        if not isinstance(name, str):
            raise ValueError(f"Each die must have a string name, {name} is not a string.")

        if not name.isalpha():
            raise ValueError(f"All die names must be alphabetic, {name} is not alphabetic.")

    for _ in range(10):  # Simulate 10 rolls per die
        roll = random.randint(1, 6)
        rolls[name] = rolls.get(name, 0) + roll

