import heapq

class MinHeap:
    def __init__(self):
        self._heap = []

    def push(self, value):
        if not isinstance(value, (int, float)):
            raise TypeError("Value must be a number")
        heapq.heappush(self._heap, value)

    def pop(self):
        if self.is_empty():
            raise ValueError("Heap is empty")
        return heapq.heappop(self._heap)

    def top(self):
        if self.is_empty():
            raise ValueError("Heap is empty")
        return self._heap[0]

    def size(self):
        return len(self._heap)

    def is_empty(self):
        return not bool(self._heap)
```

This code defines a `MinHeap` class that uses the `heapq` module to implement a min-heap. The class supports basic heap operations such as push, pop, top and size, with input validation and error handling.

