def is_valid_sudoku(board):
    rows = [set() for _ in range(9)]
    cols = [set() for _ in range(9)]
    boxes = [set() for _ in range(9)]

    def validate_number(val):
        if val < 1 or val > 9:
            raise ValueError("Invalid number")

    def get_box_index(row, col):
        return (row // 3) * 3 + (col // 3)

    # Validate rows
    for i in range(9):
        row = board[i]
        for j in row:
            val = validate_number(j)
            if val in rows[i] or val in cols[i]:
                raise ValueError("Duplicate number in row")
            rows[i].add(val)
            cols[i].add(val)

    # Validate columns
    for i in range(9):
        col = [board[j][i] for j in range(9)]
        for val in validate_number(col):
            if val in cols[i]:
                raise ValueError("Duplicate number in column")
            cols[i].add(val)

    # Validate boxes
    for i in range(9):
        box_index = get_box_index(i // 3, i % 3)
        box = [board[j][i] for j in range(3 * (i // 3), 3 * ((i // 3) + 1))]
        for val in validate_number(box):
            if val in boxes[box_index]:
                raise ValueError("Duplicate number in box")
            boxes[box_index].add(val)

    return True
