import statistics

def calculate_moving_average(numbers):
    if not numbers:
        raise ValueError("Cannot calculate moving average of empty list")

    moving_averages = []
    for i in range(len(numbers)):
        subset_sum = sum(numbers[max(0, i-5):i+1])
        num_elements_in_subset = len(numbers[max(0, i-5):i+1])
        if num_elements_in_subset == 0:
            moving_average = 0
        else:
            moving_average = subset_sum / num_elements_in_subset
        moving_averages.append(moving_average)

    return statistics.mean(moving_averages)
