import math

def distance(p1, p2):
    return math.sqrt((p1[0] - p2[0])**2 + (p1[1] - p2[1])**2)

def orientation(p1, p2, p3):
    val = (p2[1] - p1[1]) * (p3[0] - p2[0]) - (p2[0] - p1[0]) * (p3[1] - p2[1])
    if val == 0:
        return 0  # Collinear
    elif val > 0:
        return 1  # Clockwise
    else:
        return 2  # Counterclockwise

def convex_hull(points):
    n = len(points)
    if n < 3:
        raise ValueError("Convex hull not possible with less than 3 points")

    # Find the leftmost point
    hull = []
    for i in range(n):
        if not hull or points[i][0] < hull[-1][0]:
            hull.append(points[i])

    # Graham's scan to find convex hull
    for i in range(1, n):
        while len(hull) > 1 and orientation(hull[-2], hull[-1], points[i]) != 2:
            hull.pop()

    return hull

def process_query(query):
    try:
        points = [tuple(map(float, point.split(','))) for point in query['points'].split('\n')]
        convex_hull(points)
        return 'Convex Hull Points: {}\n'.format(convex_hull(points))
    except ValueError as e:
        return str(e)

# Test the function
query = """points=0,0 1,2 2,1"""
print(process_query(query))
