from typing import List, Dict

def is_bipartite(graph: Dict[int, List[int]]) -> bool:
    color = {node: -1 for node in graph}

    def dfs(node: int) -> bool:
        if color[node] == 0:
            color[node] = 0
            queue = [node]

            while queue:
                current_node = queue.pop(0)

                for neighbor in graph[current_node]:
                    if color[neighbor] == -1:
                        color[neighbor] = 1 - color[current_node]
                        queue.append(neighbor)
                    elif color[neighbor] != (1 - color[current_node]):
                        return False
            return True
        elif color[node] == 1:
            return True
        else:
            return False

    for node in graph:
        if color[node] == -1 and not dfs(node):
            return False
    return True

# Example usage:
graph = {
    0: [1, 3],
    1: [0, 2],
    2: [1, 4],
    3: [0, 4],
    4: [3]
}
print(is_bipartite(graph))  # Output: True

# Example with non-bipartite graph:
graph = {
    0: [1, 2, 3],
    1: [0],
    2: [0, 3],
    3: [0, 2]
}
print(is_bipartite(graph))  # Output: False
```

