import numpy as np

def largest_connected_component(matrix):
    if not isinstance(matrix, np.ndarray) or matrix.ndim != 2:
        raise ValueError("Input must be a 2D NumPy array")

    rows, cols = matrix.shape

    def dfs(r, c):
        if r < 0 or r >= rows or c < 0 or c >= cols or not matrix[r, c]:
            return 0
        matrix[r, c] = False  # mark as visited
        return 1 + dfs(r - 1, c) + dfs(r + 1, c) + dfs(r, c - 1) + dfs(r, c + 1)

    max_size = 0
    for r in range(rows):
        for c in range(cols):
            if matrix[r, c]:
                component_size = dfs(r, c)
                max_size = max(max_size, component_size)

    return max_size

# example usage:
matrix = np.array([[1, 1, 0], [1, 1, 0], [0, 0, 1]])
print(largest_connected_component(matrix))
