import os
import hashlib

def remove_duplicate_files(directory):
    # Create a dictionary to store file hashes
    file_hashes = {}

    # Iterate over all files in the directory and its subdirectories
    for root, dirs, files in os.walk(directory):
        for file in files:
            # Skip empty files
            if not os.path.getsize(os.path.join(root, file)):
                continue

            # Calculate the file hash using SHA-256
            file_hash = hashlib.sha256(open(os.path.join(root, file), 'rb').read()).hexdigest()

            # If the file hash is already in the dictionary, skip this iteration
            if file_hash in file_hashes:
                print(f"Skipping {os.path.join(root, file)} as it's a duplicate")
            else:
                file_hashes[file_hash] = True

    # Remove duplicates by iterating over the dictionary and deleting files
    for root, dirs, files in os.walk(directory):
        for file in files:
            # Skip empty files
            if not os.path.getsize(os.path.join(root, file)):
                continue

            # Calculate the file hash using SHA-256
            file_hash = hashlib.sha256(open(os.path.join(root, file), 'rb').read()).hexdigest()

            # If the file hash is in the dictionary, delete the file
            if file_hash in file_hashes:
                os.remove(os.path.join(root, file))

remove_duplicate_files('/path/to/directory')
