```python
import random
from enum import Enum

class CardSuit(Enum):
    HEARTS = 1
    DIAMONDS = 2
    CLUBS = 3
    SPADES = 4

class CardRank(Enum):
    TWO = 2
    THREE = 3
    FOUR = 4
    FIVE = 5
    SIX = 6
    SEVEN = 7
    EIGHT = 8
    NINE = 9
    TEN = 10
    JACK = 11
    QUEEN = 12
    KING = 13
    ACE = 14

class Card:
    def __init__(self, suit: CardSuit, rank: CardRank):
        self.suit = suit
        self.rank = rank

    def __repr__(self):
        return f"{self.rank.name} of {self.suit.name}"

class Deck:
    def __init__(self):
        self.cards = []
        for suit in CardSuit:
            for rank in CardRank:
                self.cards.append(Card(suit, rank))

    def shuffle(self):
        if not self.cards:
            raise ValueError("The deck is empty")
        random.shuffle(self.cards)

    def deal_card(self):
        if not self.cards:
            raise ValueError("The deck is empty")
        return self.cards.pop()

class Player:
    def __init__(self, name: str):
        if not isinstance(name, str) or len(name.strip()) == 0:
            raise ValueError("Player's name must be a non-empty string")
        self.name = name
        self.hand = []

    def draw_card(self, deck: Deck):
        card = deck.deal_card()
        self.hand.append(card)

    def play_card(self):
        if not self.hand:
            raise ValueError("The player does not have any cards in their hand")
        return self.hand.pop(0)
```

This class-based implementation provides secure and robust support for shuffling and dealing a deck of cards, including input validation and error handling.

