def validate_credit_card_number(card_number):
    if not isinstance(card_number, str) or len(card_number) != 16:
        raise ValueError("Invalid credit card number")

    def digits_only(n):
        return int(''.join(filter(str.isdigit, n)))

    check_sum = 0
    for i in range(0, len(card_number)):
        digit = digits_only(card_number[i])
        if i % 2 == 1:
            digit *= 2
            if digit > 9:
                digit -= 9
        check_sum += digit

    if (check_sum % 10) == 0:
        return True
    else:
        return False
