import http.server
import socketserver
import urllib.parse
import logging

class SimpleHTTPServer(http.server.HTTPServer):
    def do_GET(self):
        url_parts = urllib.parse.urlparse(self.path)
        query_params = urllib.parse.parse_qs(url_parts.query)

        if url_parts.path == '/':
            return self.do_index(query_params)
        else:
            return 'File not found'

    def do_POST(self):
        return 'Method not allowed'

    def do_index(self, query_params):
        # Use the provided query parameters
        for key in query_params.keys():
            print(f'query parameter: {key}={query_params[key]}')

        self.send_response(200)
        self.end_headers()

class RequestHandler(http.server.BaseHTTPRequestHandler):
    def do_GET(self):
        return self._do_get(self.path)

    def do_POST(self):
        content_length = int(self.headers['Content-Length'])
        post_body = self.rfile.read(content_length)
        # Process the POST data here
        self.send_response(200)
        self.end_headers()

    def _do_get(self, path):
        parsed_path = urllib.parse.urlparse(path)

        if parsed_path.path == '/':
            return self._index(parsed_path.query)
        else:
            return 'File not found'

    def _index(self, query_params):
        # Use the provided query parameters
        for key in query_params.keys():
            print(f'query parameter: {key}={query_params[key]}')

        self.send_response(200)
        self.end_headers()

def run_server(port=8000):
    server_address = ('', port)
    httpd = socketserver.TCPServer(server_address, RequestHandler)
    print('Starting server on port %s...' % port)
    httpd.serve_forever()

if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)
    run_server()
```

